CREATE FUNCTION pg_temp.r0(res jsonb, n int DEFAULT 0) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$ SELECT res -> 'results' -> n $h$;
CREATE FUNCTION pg_temp.st(res jsonb, n int DEFAULT 0) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT coalesce(res -> 'results' -> n ->> 'status', 'ERROR:' || coalesce(res ->> 'error', res::text))
$h$;
CREATE FUNCTION pg_temp.nowt(off interval DEFAULT '0') RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT to_char((clock_timestamp() + off) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
$h$;

-- BACKLOG-4263 PR-10.7 harness: helpers and fixtures, loaded BEFORE the migration (inside the same rolled-back call).
-- Every id, name, email and secret is invented and derived from 'notice-harness'; user ids start 00000000-. Rows of
-- the reserved account and of the live AI-app connection are never read or written. Only counts, fixture keys and
-- statuses are recorded.
-- Connections are made by the real producers: mcp_authorize_begin (anon), mcp_authorize_view and
-- mcp_authorize_approve (the signed-in user), then mcp_exchange_code (anon). Set directly, each for this call only and
-- rolled back with everything else:
--   mcp_settings: the portal secret is a fixture value in portal_secret_prev_sha256 (and in portal_secret_sha256 only
--   when that is empty); enabled = true; connect_requires_cloud = false (the setting approve reads, so the fixture
--   users need no Cloud plan);
--   mcp_authorization_codes.expires_at of one code, moved to the past (approve writes now() + 60 s; one transaction
--   cannot wait for it);
--   rows of ai_app_connect_notices for the claim and done controls (their columns are the ones the exchange and the
--   two functions write; connected_at, attempts and lease_until are moved in time for the same reason).

CREATE TEMP TABLE pn_out (o serial, k text, v jsonb);
CREATE FUNCTION pg_temp.rec(k text, v jsonb) RETURNS void LANGUAGE sql AS $h$ INSERT INTO pg_temp.pn_out (k, v) VALUES (k, v) $h$;
CREATE TEMP TABLE pn_fx (k text PRIMARY KEY, v text);
CREATE FUNCTION pg_temp.id(k text) RETURNS uuid LANGUAGE sql STABLE AS $h$ SELECT v::uuid FROM pg_temp.pn_fx WHERE pn_fx.k = id.k $h$;
CREATE FUNCTION pg_temp.put(k text, v text) RETURNS void LANGUAGE sql AS $h$
  INSERT INTO pg_temp.pn_fx VALUES (k, v) ON CONFLICT (k) DO UPDATE SET v = excluded.v $h$;
-- a fixture user id: 00000000-0000-4000-8000-0000426307<n, 2 digits>
CREATE FUNCTION pg_temp.uid(n int) RETURNS uuid LANGUAGE sql IMMUTABLE AS $h$
  SELECT ('00000000-0000-4000-8000-0000426307' || lpad(n::text, 2, '0'))::uuid $h$;

CREATE FUNCTION pg_temp.secret() RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT 'pn-fixture-portal-secret-' || md5('notice-harness') $h$;
CREATE FUNCTION pg_temp.res() RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT 'https://pn-fixture.example.test/api/mcp' $h$;
CREATE FUNCTION pg_temp.client() RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT 'kpr_c_' || substr(md5('notice-harness-client'), 1, 22) $h$;
CREATE FUNCTION pg_temp.redir(prov text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT CASE prov WHEN 'anthropic' THEN 'https://claude.ai/api/mcp/auth_callback' ELSE 'https://chatgpt.com/connector_platform_oauth_redirect' END $h$;
-- token digest n (what the portal sends) as a bytea text literal; code digest and verifier of consent k
CREATE FUNCTION pg_temp.dgl(n int) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT '\x' || encode(sha256(convert_to('pn-at-' || md5('notice-harness') || n, 'UTF8')), 'hex') $h$;
CREATE FUNCTION pg_temp.cd(k text) RETURNS bytea LANGUAGE sql IMMUTABLE AS $h$ SELECT sha256(convert_to('pn-code-' || k, 'UTF8')) $h$;
CREATE FUNCTION pg_temp.cdl(k text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT '\x' || encode(pg_temp.cd(k), 'hex') $h$;
CREATE FUNCTION pg_temp.ver(k text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT 'v' || md5(k) || md5(k || 'x') $h$;

-- one call as anon with the claims PostgREST sets; an error comes back as {"sqlerr", "msg"}
CREATE FUNCTION pg_temp.w(q text) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE x_r jsonb;
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"anon"}', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claim.role', '', true);
  EXECUTE 'SET LOCAL ROLE anon';
  BEGIN
    EXECUTE q INTO x_r;
  EXCEPTION WHEN OTHERS THEN x_r := jsonb_build_object('sqlerr', SQLSTATE, 'msg', left(SQLERRM, 200));
  END;
  EXECUTE 'RESET ROLE';
  PERFORM pg_temp.clear_claims();
  RETURN x_r;
END $h$;

-- begin -> view -> approve for user u and provider prov; the code is pg_temp.cd(k), the verifier pg_temp.ver(k)
CREATE FUNCTION pg_temp.consent(k text, u uuid, prov text) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE x_bind text := '\x' || encode(sha256(convert_to('pn-bind-' || k, 'UTF8')), 'hex'); x_b jsonb; x_v jsonb; x_a jsonb; x_rid text;
BEGIN
  x_b := pg_temp.w(format('SELECT public.mcp_authorize_begin(%L, %L, %L, %L, %L, %L, %L, NULL, %L::bytea, %L::bytea)', pg_temp.secret(), pg_temp.client(),
           pg_temp.redir(prov), public._mcp_b64url(sha256(convert_to(pg_temp.ver(k), 'UTF8'))), 'S256', pg_temp.res(), 'mcp:read',
           x_bind, '\x' || encode(sha256(convert_to('pn-ip-' || k, 'UTF8')), 'hex')));
  x_rid := x_b ->> 'request_id';
  IF x_rid IS NULL THEN
    RETURN jsonb_build_object('step', 'begin', 'r', x_b);
  END IF;
  x_v := pg_temp.rpc(u, format('SELECT public.mcp_authorize_view(%L, %L::bytea)', x_rid, x_bind));
  IF x_v ->> 'nonce' IS NULL THEN
    RETURN jsonb_build_object('step', 'view', 'r', x_v);
  END IF;
  x_a := pg_temp.rpc(u, format('SELECT public.mcp_authorize_approve(%L, %L::bytea, %L, %L::bytea)', x_rid, x_bind, x_v ->> 'nonce', pg_temp.cdl(k)));
  RETURN jsonb_build_object('step', 'approve', 'ok', x_a -> 'ok', 'r', x_a - 'redirect_uri' - 'state');
END $h$;

-- the exchange call (function fn) for consent k; each override replaces one argument
CREATE FUNCTION pg_temp.q_ex(k text, prov text, n int, fn text DEFAULT 'mcp_exchange_code', ver_o text DEFAULT NULL, code_o text DEFAULT NULL,
                             sec_o text DEFAULT NULL, redir_o text DEFAULT NULL, res_o text DEFAULT NULL, rt_n int DEFAULT NULL) RETURNS text LANGUAGE sql STABLE AS $h$
  SELECT format('SELECT public.%I(%L, %L::bytea, %L, %L, %L, %L, %L::bytea, %L::bytea)', fn, coalesce(sec_o, pg_temp.secret()),
                coalesce(code_o, pg_temp.cdl(k)), coalesce(ver_o, pg_temp.ver(k)), pg_temp.client(), coalesce(redir_o, pg_temp.redir(prov)),
                coalesce(res_o, pg_temp.res()), pg_temp.dgl(n), pg_temp.dgl(coalesce(rt_n, n + 500)))
$h$;
CREATE FUNCTION pg_temp.ok_answer() RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT '{"ok":true,"token_type":"Bearer","expires_in":3600,"scope":"mcp:read"}'::jsonb $h$;

-- the notices, by fixture user key ('A', 'B', 'C', or '?' for a user that is not a fixture)
CREATE FUNCTION pg_temp.ukey(u uuid) RETURNS text LANGUAGE sql STABLE AS $h$
  SELECT coalesce((SELECT f.k FROM pg_temp.pn_fx f WHERE f.k IN ('A', 'B', 'C') AND f.v = u::text), '?') $h$;
-- what an exchange changes besides the notices: the user's connections, tokens, used codes and log events
CREATE FUNCTION pg_temp.effects(u uuid) RETURNS jsonb LANGUAGE sql STABLE AS $h$
  SELECT jsonb_build_object(
    'conns', (SELECT coalesce(jsonb_agg(c.status || ' ' || c.provider ORDER BY c.status, c.provider), '[]') FROM public.mcp_connections c WHERE c.user_id = u),
    'tokens', (SELECT count(*) FROM public.mcp_tokens t JOIN public.mcp_connections c ON c.id = t.connection_id WHERE c.user_id = u),
    'codes_used', (SELECT count(*) FROM public.mcp_authorization_codes x JOIN public.mcp_connections c ON c.id = x.connection_id
                    WHERE c.user_id = u AND x.used_at IS NOT NULL),
    'log', (SELECT coalesce(jsonb_agg(l.event || ' ' || l.outcome ORDER BY l.event, l.outcome), '[]') FROM public.mcp_call_log l WHERE l.user_id = u),
    'tok_fail', (SELECT coalesce(sum(r.count), 0) FROM public.mcp_rate_counters r WHERE r.bucket = 'tok_fail:' || pg_temp.client()))
$h$;

DO $fxn$
DECLARE x_s record;
BEGIN
  SET LOCAL session_replication_role = replica;
  INSERT INTO auth.users (id, email, aud, role, instance_id, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
  SELECT pg_temp.uid(n), 'p4263-notice-' || substr(md5('notice-harness'), 1, 8) || '-' || n || '@example.test', 'authenticated', 'authenticated',
         '00000000-0000-0000-0000-000000000000', '{"provider":"email"}', '{}', now(), now() FROM generate_series(1, 3) n;
  SET LOCAL session_replication_role = origin;
  PERFORM pg_temp.put('A', pg_temp.uid(1)::text); PERFORM pg_temp.put('B', pg_temp.uid(2)::text); PERFORM pg_temp.put('C', pg_temp.uid(3)::text);

  SELECT s.enabled, s.connect_requires_cloud, s.portal_secret_sha256 IS NOT NULL AS has_current INTO x_s FROM public.mcp_settings s WHERE s.id;
  PERFORM pg_temp.rec('fx_settings_before', jsonb_build_object('enabled', x_s.enabled, 'connect_requires_cloud', x_s.connect_requires_cloud,
                                                               'current_secret_set', x_s.has_current));
  UPDATE public.mcp_settings
     SET portal_secret_prev_sha256 = sha256(convert_to(pg_temp.secret(), 'UTF8')),
         portal_secret_sha256 = coalesce(portal_secret_sha256, sha256(convert_to('pn-fixture-current-' || md5('notice-harness'), 'UTF8'))),
         enabled = true, connect_requires_cloud = false
   WHERE id;
  INSERT INTO public.mcp_oauth_clients (client_id, client_name, redirect_uris, ip_sha256)
  VALUES (pg_temp.client(), 'Fixture app', ARRAY[pg_temp.redir('anthropic'), pg_temp.redir('openai')], sha256(convert_to('pn-ip', 'UTF8')));
  PERFORM pg_temp.rec('fx_allowlist', jsonb_build_object(
    'anthropic', EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = pg_temp.redir('anthropic') AND a.provider = 'anthropic'),
    'openai', EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = pg_temp.redir('openai') AND a.provider = 'openai')));
END
$fxn$;

DO $t0$
BEGIN
  PERFORM pg_temp.rec('t_start', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('exchange_md5_before_apply', to_jsonb((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure)));
  PERFORM pg_temp.rec('exchange_md5_expected_before', to_jsonb('ab6a9345c55ab69c77347d9b37e92e9d'::text));
  PERFORM pg_temp.rec('migration_md5', to_jsonb('01de24669ca539eef64383b4c42153dd'::text));
  PERFORM pg_temp.rec('ledger_20261118160000', to_jsonb((SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118160000')));
  PERFORM pg_temp.rec('ledger_20261118170000', to_jsonb((SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118170000')));
  PERFORM pg_temp.rec('authorize_view_md5', to_jsonb((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_authorize_view(text,bytea)'::regprocedure)));
  PERFORM pg_temp.rec('locks_auth_users_before_apply', (SELECT coalesce(jsonb_agg(DISTINCT l.mode), '[]') FROM pg_locks l WHERE l.pid = pg_backend_pid() AND l.relation = 'auth.users'::regclass));
END $t0$;
-- ================================================================ apply
-- apply-20261118180000.sql (generated by supabase/tests/backlog-4263-notice/gen.py; do not hand-edit)
-- Migration: supabase/migrations/20261118180000_backlog_4263_ai_app_connect_notice.sql  file md5 01de24669ca539eef64383b4c42153dd
-- One transaction. If the apply tool writes the ledger row itself, remove the INSERT below.
-- The post-check RAISEs (rolling everything back) unless: mcp_exchange_code is at md5 9a33bff2db31288bd77a57489558a65b and is the only
-- function in schema public that changed (body md5, grants, settings, security definer, owner, volatility, strict,
-- leakproof, parallel, cost, rows), and only its body changed; exactly ai_app_notice_claim and ai_app_notice_done were
-- added, owned by postgres, plpgsql VOLATILE SECURITY DEFINER with an empty search_path, EXECUTE for postgres and
-- service_role only; no function was dropped; exactly the table ai_app_connect_notices and its three indexes were
-- added (RLS on, no policy, no privilege for any role but its owner, one unique index (the key), one foreign key (to
-- auth.users), the ten named columns); no other relation in public changed its grants, RLS or policy count; the
-- anon-callable mcp functions are exactly the 17 named and no ai_app_ function is anon-callable; the ledger row.
CREATE TEMP TABLE pn_fn_before AS
  SELECT p.oid::regprocedure::text AS sig, md5(p.prosrc) AS src_md5, p.proacl::text AS acl, p.proconfig AS config, p.prosecdef AS secdef,
         p.proowner AS owner, p.provolatile AS vol, p.proisstrict AS strict, p.proleakproof AS leakproof, p.proparallel AS parallel,
         p.procost AS cost, p.prorows AS nrows
    FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace;
CREATE TEMP TABLE pn_rel_before AS
  SELECT c.relname::text AS rel, c.relkind::text AS kind, c.relacl::text AS acl, c.relrowsecurity AS rls, c.relforcerowsecurity AS frls,
         c.relowner AS owner, (SELECT count(*) FROM pg_policy y WHERE y.polrelid = c.oid) AS npol
    FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace;

-- ============================================================================
-- Migration: a notice when an AI app connects (BACKLOG-4263 PR-10.7)
--
-- New table public.ai_app_connect_notices: one row per AI-app connection that turned active, read later by the
--   portal's email job (a later PR). It holds whose account, which provider, whether the connection replaced an
--   earlier one, and the sending state. No token, no connection id, no text supplied by the app. RLS on, no policy,
--   no privilege for any API role; reached only through the two functions below.
-- Replaced (pre-check below): mcp_exchange_code (anon, portal secret checked first, as before). The one change: after
--   the tokens are stored, one INSERT into the new table, in its own BEGIN ... EXCEPTION WHEN OTHERS block (one
--   subtransaction per exchange), so an error there never fails the exchange. The answer is unchanged. 'replaced'
--   is v_n > 0, the row count of the DELETE of the user's earlier active connection to the same redirect address.
--   The body is otherwise character-identical to the body of 20261118130000 (the marker comment aside).
-- New: ai_app_notice_claim(p_limit) and ai_app_notice_done(p_id, p_attempts, p_status, p_error), SECURITY DEFINER,
--   EXECUTE service_role only, each refusing inside unless the request's role is service_role.
--   claim: housekeeping first (a due notice older than 2 days -> skipped 'stale'; a due notice tried 5 times with its
--   lease ended -> failed; finished notices older than 30 days deleted), then up to min(p_limit, 50) due notices with
--   no live lease, FOR UPDATE SKIP LOCKED, each leased for 5 minutes and its attempts incremented. Answers a JSON
--   array of {id, user_id, provider, replaced, connected_at, attempts}.
--   done: sets the status ('due' releases the lease for a retry) only while the row is due and its attempts equal
--   p_attempts; the error code is cut to 40 characters. Answers true when a row changed.
-- Existing rows: none changed. Connections made before this file get no notice.
-- Pre-check: mcp_exchange_code is at the body of 20261118130000 (md5 ab6a9345c55ab69c77347d9b37e92e9d) or already at this
--   file's body (md5 9a33bff2db31288bd77a57489558a65b); otherwise nothing is applied.
-- Re-runnable: CREATE TABLE / INDEX IF NOT EXISTS, CREATE OR REPLACE.
-- Rollback: supabase/tests/backlog-4263-notice/rollback-20261118180000.sql (run it before any rollback of
--   20261118130000).
-- ============================================================================

DO $pre4263notice$
DECLARE v_md5 text;
BEGIN
  SELECT md5(p.prosrc) INTO v_md5 FROM pg_catalog.pg_proc p
   WHERE p.oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)');
  IF v_md5 IS NULL OR v_md5 NOT IN ('ab6a9345c55ab69c77347d9b37e92e9d', '9a33bff2db31288bd77a57489558a65b') THEN
    RAISE EXCEPTION 'BACKLOG-4263: public.mcp_exchange_code is not at the expected body (md5 %)', coalesce(v_md5, 'missing');
  END IF;
END
$pre4263notice$;

-- ============================================================================ table
CREATE TABLE IF NOT EXISTS public.ai_app_connect_notices (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL REFERENCES auth.users (id) ON DELETE CASCADE,
  provider     text NOT NULL CHECK (provider IN ('anthropic', 'openai')),
  replaced     boolean NOT NULL,
  connected_at timestamptz NOT NULL DEFAULT now(),
  status       text NOT NULL DEFAULT 'due' CHECK (status IN ('due', 'sent', 'queued', 'failed', 'skipped')),
  attempts     smallint NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  lease_until  timestamptz NULL,
  sent_at      timestamptz NULL,
  last_error   text NULL CHECK (last_error IS NULL OR char_length(last_error) <= 40)
);
CREATE INDEX IF NOT EXISTS ai_app_connect_notices_due_idx ON public.ai_app_connect_notices (connected_at) WHERE status = 'due';
CREATE INDEX IF NOT EXISTS ai_app_connect_notices_user_idx ON public.ai_app_connect_notices (user_id);
ALTER TABLE public.ai_app_connect_notices ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.ai_app_connect_notices FROM PUBLIC, anon, authenticated, service_role;
REVOKE TRUNCATE ON TABLE public.ai_app_connect_notices FROM anon, authenticated;

-- ============================================================================ exchange (anon)
-- 4263 PR-5: answers the connection's scope. 4263 PR-10.7: records one notice when the connection turns active.
-- Intentionally callable by anon: OAuth token exchange for a registered client (portal secret checked inside)
CREATE OR REPLACE FUNCTION public.mcp_exchange_code(p_secret text, p_code_digest bytea, p_code_verifier text, p_client_id text, p_redirect_uri text,
                                                    p_resource text, p_at_digest bytea, p_rt_digest bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_code   public.mcp_authorization_codes%ROWTYPE;
  v_used   public.mcp_authorization_codes%ROWTYPE;
  v_user   uuid;
  v_redir  text;
  v_pepper smallint;
  v_n      integer;
  v_scope  text;
BEGIN
  /*BODY:4263-10.7*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;
  IF (octet_length(p_code_digest) = 32 AND octet_length(p_at_digest) = 32 AND octet_length(p_rt_digest) = 32
      AND p_at_digest IS DISTINCT FROM p_rt_digest) IS NOT TRUE THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END IF;

  -- token insert failure: everything in this block is rolled back (code not used up)
  BEGIN
  UPDATE public.mcp_authorization_codes k
     SET used_at = now()
   WHERE k.code_sha256 = sha256(p_code_digest)
     AND k.used_at IS NULL
     AND k.expires_at > now()
  RETURNING k.* INTO v_code;

  IF v_code.code_sha256 IS NULL THEN
    -- a used code presented again: the connection is removed only when the request is otherwise
    -- valid for that code (client, verifier, and redirect address when sent)
    SELECT k.* INTO v_used
      FROM public.mcp_authorization_codes k
     WHERE k.code_sha256 = sha256(p_code_digest)
       AND k.used_at IS NOT NULL;
    IF v_used.code_sha256 IS NOT NULL THEN
      SELECT c.user_id INTO v_user FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
      IF (v_used.client_id = p_client_id
          AND (p_redirect_uri IS NULL OR v_used.redirect_uri = p_redirect_uri)
          AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
          AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_used.code_challenge) IS TRUE THEN
        DELETE FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay', 'ok', now());
      ELSIF public._mcp_bump('replay_refused:' || v_used.connection_id::text, interval '1 hour', 5) IS NOT DISTINCT FROM 'ok' THEN
        -- at most 5 refused-replay events per connection per hour; the response is the same either way
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay_refused', 'ok', now());
      END IF;
    END IF;
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  -- a rejected redemption uses up the code and removes its pending connection
  IF (v_code.client_id = p_client_id
      AND (p_redirect_uri IS NULL OR v_code.redirect_uri = p_redirect_uri)
      AND v_code.resource = p_resource
      AND EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = v_code.redirect_uri)
      AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
      AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_code.code_challenge) IS NOT TRUE THEN
    DELETE FROM public.mcp_connections c
     WHERE c.id = v_code.connection_id AND c.status = 'pending'
    RETURNING c.user_id INTO v_user;
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
    VALUES (v_user, v_code.connection_id, 'code_rejected', 'ok', now());
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  UPDATE public.mcp_connections c
     SET status = 'active', activated_at = now()
   WHERE c.id = v_code.connection_id
     AND c.status = 'pending'
  RETURNING c.user_id, c.redirect_uri, c.scope INTO v_user, v_redir, v_scope;
  IF v_user IS NULL THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;

  DELETE FROM public.mcp_connections c
   WHERE c.user_id = v_user AND c.redirect_uri = v_redir AND c.id <> v_code.connection_id AND c.status = 'active';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at, rows_returned)
    VALUES (v_user, v_code.connection_id, 'reconnect_replaced', 'ok', now(), v_n);
  END IF;

  SELECT s.pepper_version INTO v_pepper FROM public.mcp_settings s WHERE s.id;
  BEGIN
    INSERT INTO public.mcp_tokens (token_sha256, connection_id, kind, pepper_version, expires_at) VALUES
      (sha256(p_at_digest), v_code.connection_id, 'access', v_pepper, now() + interval '1 hour'),
      (sha256(p_rt_digest), v_code.connection_id, 'refresh', v_pepper, now() + interval '30 days');
  EXCEPTION WHEN unique_violation OR not_null_violation THEN
    RAISE EXCEPTION USING ERRCODE = 'MC001', MESSAGE = 'mcp token insert failed';
  END;
  -- 4263 PR-10.7: one notice for the connection that just turned active, read later by the email job. In its own
  -- block: any error here discards the notice only; the exchange and its answer are unchanged.
  BEGIN
    INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced)
    SELECT c.user_id, c.provider, v_n > 0 FROM public.mcp_connections c WHERE c.id = v_code.connection_id;   /*NOTICE:exchange*/
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN jsonb_build_object('ok', true, 'token_type', 'Bearer', 'expires_in', 3600, 'scope', v_scope);   /*SCOPE:exchange*/
  EXCEPTION WHEN SQLSTATE 'MC001' THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END;
END
$fn$;
REVOKE ALL ON FUNCTION public.mcp_exchange_code(text, bytea, text, text, text, text, bytea, bytea) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mcp_exchange_code(text, bytea, text, text, text, text, bytea, bytea) TO anon;

-- ============================================================================ email job (service_role)
CREATE OR REPLACE FUNCTION public.ai_app_notice_claim(p_limit integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_rows jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN   /*CALLER:claim*/
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  UPDATE public.ai_app_connect_notices n
     SET status = 'skipped', last_error = 'stale', lease_until = NULL
   WHERE n.id IN (SELECT x.id FROM public.ai_app_connect_notices x
                   WHERE x.status = 'due' AND x.connected_at < now() - interval '2 days'   /*STALE:skip*/
                   LIMIT 500 FOR UPDATE SKIP LOCKED);
  UPDATE public.ai_app_connect_notices n
     SET status = 'failed', last_error = coalesce(n.last_error, 'attempts'), lease_until = NULL
   WHERE n.id IN (SELECT x.id FROM public.ai_app_connect_notices x
                   WHERE x.status = 'due' AND x.attempts >= 5 AND (x.lease_until IS NULL OR x.lease_until <= now())
                   LIMIT 500 FOR UPDATE SKIP LOCKED);
  DELETE FROM public.ai_app_connect_notices n
   WHERE n.id IN (SELECT x.id FROM public.ai_app_connect_notices x
                   WHERE x.status IN ('sent', 'queued', 'failed', 'skipped') AND x.connected_at < now() - interval '30 days'   /*KEEP:30d*/
                   LIMIT 500 FOR UPDATE SKIP LOCKED);
  WITH c AS (
    SELECT x.id FROM public.ai_app_connect_notices x
     WHERE x.status = 'due'
       AND x.attempts < 5   /*CAP:attempts*/
       AND (x.lease_until IS NULL OR x.lease_until <= now())   /*LEASE:free*/
       AND x.connected_at >= now() - interval '2 days'   /*STALE:claim*/
     ORDER BY x.connected_at, x.id
     LIMIT least(greatest(coalesce(p_limit, 0), 0), 50)   /*CAP:limit*/
     FOR UPDATE SKIP LOCKED),
  u AS (
    UPDATE public.ai_app_connect_notices n
       SET attempts = n.attempts + 1, lease_until = now() + interval '5 minutes'
      FROM c
     WHERE n.id = c.id
    RETURNING n.id, n.user_id, n.provider, n.replaced, n.connected_at, n.attempts)
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'user_id', u.user_id, 'provider', u.provider, 'replaced', u.replaced,
                                               'connected_at', u.connected_at, 'attempts', u.attempts) ORDER BY u.connected_at, u.id), '[]'::jsonb)   /*KEYS:claim*/
    INTO v_rows
    FROM u;
  RETURN v_rows;
END
$fn$;
REVOKE ALL ON FUNCTION public.ai_app_notice_claim(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ai_app_notice_claim(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.ai_app_notice_done(p_id uuid, p_attempts integer, p_status text, p_error text)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_n integer;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN   /*CALLER:done*/
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF (p_status IN ('due', 'sent', 'queued', 'failed', 'skipped')) IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ai_app_notice_done: unknown status';
  END IF;
  UPDATE public.ai_app_connect_notices n
     SET status = p_status,
         last_error = left(p_error, 40),   /*CUT:error*/
         lease_until = NULL,
         sent_at = CASE WHEN p_status IN ('sent', 'queued') THEN now() ELSE n.sent_at END
   WHERE n.id = p_id
     AND n.attempts = p_attempts   /*GUARD:attempts*/
     AND n.status = 'due';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n = 1;
END
$fn$;
REVOKE ALL ON FUNCTION public.ai_app_notice_done(uuid, integer, text, text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ai_app_notice_done(uuid, integer, text, text) TO service_role;

-- Post-check: bodies, attributes and grants of the three functions; the table closed; the anon-callable mcp count.
DO $post4263notice$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'exchange', (SELECT md5(p.prosrc) = '9a33bff2db31288bd77a57489558a65b' AND p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""'
                        AND has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
                        AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
                   FROM pg_catalog.pg_proc p WHERE p.oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure),
    'jobs', (SELECT bool_and(p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""' AND p.proowner = 'postgres'::regrole::oid
                             AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND NOT has_function_privilege('anon', p.oid, 'EXECUTE')
                             AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')) AND count(*) = 2
               FROM pg_catalog.pg_proc p WHERE p.oid IN ('public.ai_app_notice_claim(integer)'::regprocedure,
                                                         'public.ai_app_notice_done(uuid,integer,text,text)'::regprocedure)),
    'table', (SELECT c.relrowsecurity AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_policy y WHERE y.polrelid = c.oid)
                     AND NOT has_table_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
                     AND NOT has_table_privilege('authenticated', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
                     AND NOT has_table_privilege('service_role', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
                FROM pg_catalog.pg_class c WHERE c.oid = 'public.ai_app_connect_notices'::regclass),
    'anon_mcp', (SELECT count(*) FROM pg_catalog.pg_proc p
                  WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE')),
    'anon_jobs', (SELECT count(*) FROM pg_catalog.pg_proc p
                   WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^ai_app_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))) INTO v;
  IF (v ->> 'exchange')::boolean IS NOT TRUE OR (v ->> 'jobs')::boolean IS NOT TRUE OR (v ->> 'table')::boolean IS NOT TRUE
     OR (v ->> 'anon_mcp')::int IS DISTINCT FROM 17 OR (v ->> 'anon_jobs')::int IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'BACKLOG-4263: notice post-check failed: %', v;
  END IF;
END
$post4263notice$;

INSERT INTO supabase_migrations.schema_migrations (version, name, statements)
VALUES ('20261118180000', 'backlog_4263_ai_app_connect_notice', ARRAY[]::text[]);

DO $postnotice$
DECLARE v jsonb; w_changed jsonb; w_added jsonb; w_rel jsonb;
BEGIN
  SELECT jsonb_build_object(
    'exchange_md5', (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure),
    'exchange_md5_before', (SELECT b.src_md5 FROM pg_temp.pn_fn_before b WHERE b.sig = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text),
    'exchange_attributes_unchanged', EXISTS (SELECT 1 FROM pg_temp.pn_fn_before b JOIN pg_proc p ON p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows WHERE b.sig = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text),
    'changed', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pn_fn_before b
         WHERE EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig) AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows AND md5(p.prosrc) = b.src_md5)),
    'gone', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pn_fn_before b WHERE NOT EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig)),
    'added', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pn_fn_before b WHERE b.sig = p.oid::regprocedure::text)),
    'jobs_owner_definer_path_grants', (SELECT count(*) = 2 AND bool_and(p.proowner = 'postgres'::regrole::oid AND p.prosecdef AND p.provolatile = 'v'
          AND p.prolang = (SELECT l.oid FROM pg_language l WHERE l.lanname = 'plpgsql') AND array_to_string(p.proconfig, ',') = 'search_path=""'
          AND (SELECT array_agg(DISTINCT a.grantee::regrole::text ORDER BY a.grantee::regrole::text) FROM aclexplode(p.proacl) a
                WHERE a.privilege_type = 'EXECUTE') = ARRAY['postgres', 'service_role'])
        FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.ai_app_notice_claim(integer)'), to_regprocedure('public.ai_app_notice_done(uuid,integer,text,text)'))),
    'table_closed_columns_keys', (SELECT c.relrowsecurity AND c.relowner = 'postgres'::regrole::oid
          AND NOT EXISTS (SELECT 1 FROM pg_policy y WHERE y.polrelid = c.oid)
          AND NOT EXISTS (SELECT 1 FROM aclexplode(c.relacl) a WHERE a.grantee <> c.relowner)
          AND (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid AND i.indisunique) = 1
          AND (SELECT array_agg(k.confrelid::regclass::text) FROM pg_constraint k WHERE k.conrelid = c.oid AND k.contype = 'f') = ARRAY['auth.users']
          AND (SELECT array_agg(a.attname::text ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped)
              = ARRAY['id', 'user_id', 'provider', 'replaced', 'connected_at', 'status', 'attempts', 'lease_until', 'sent_at', 'last_error']
        FROM pg_class c WHERE c.oid = to_regclass('public.ai_app_connect_notices')),
    'rel_changed', (SELECT coalesce(array_agg(b.rel ORDER BY b.rel COLLATE "C"), '{}') FROM pg_temp.pn_rel_before b
         WHERE EXISTS (SELECT 1 FROM pg_class c2 WHERE c2.relnamespace = 'public'::regnamespace AND c2.relname::text = b.rel) AND NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relname::text = b.rel AND c.relkind::text = b.kind AND c.relacl::text IS NOT DISTINCT FROM b.acl
                   AND c.relrowsecurity = b.rls AND c.relforcerowsecurity = b.frls AND c.relowner = b.owner
                   AND (SELECT count(*) FROM pg_policy y WHERE y.polrelid = c.oid) = b.npol)),
    'rel_gone', (SELECT coalesce(array_agg(b.rel ORDER BY b.rel COLLATE "C"), '{}') FROM pg_temp.pn_rel_before b WHERE NOT EXISTS (SELECT 1 FROM pg_class c2 WHERE c2.relnamespace = 'public'::regnamespace AND c2.relname::text = b.rel)),
    'rel_added', (SELECT coalesce(array_agg(c.relname::text ORDER BY c.relname::text COLLATE "C"), '{}') FROM pg_class c
        WHERE c.relnamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pn_rel_before b WHERE b.rel = c.relname::text)),
    'anon_mcp_17', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'anon_ai_app', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^ai_app_'
        AND has_function_privilege('anon', p.oid, 'EXECUTE')),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118180000')) INTO v;
  w_changed := CASE WHEN v ->> 'exchange_md5_before' = '9a33bff2db31288bd77a57489558a65b' THEN '[]'::jsonb ELSE jsonb_build_array('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text) END;
  SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"), '[]') INTO w_added
    FROM unnest(ARRAY['public.ai_app_notice_claim(integer)'::regprocedure::text, 'public.ai_app_notice_done(uuid,integer,text,text)'::regprocedure::text]) x WHERE NOT EXISTS (SELECT 1 FROM pg_temp.pn_fn_before b WHERE b.sig = x);
  SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"), '[]') INTO w_rel
    FROM unnest(ARRAY['ai_app_connect_notices', 'ai_app_connect_notices_due_idx', 'ai_app_connect_notices_pkey', 'ai_app_connect_notices_user_idx']) x WHERE NOT EXISTS (SELECT 1 FROM pg_temp.pn_rel_before b WHERE b.rel = x);
  IF v ->> 'exchange_md5' IS DISTINCT FROM '9a33bff2db31288bd77a57489558a65b'
     OR v -> 'changed' IS DISTINCT FROM w_changed OR v -> 'added' IS DISTINCT FROM w_added OR v -> 'gone' IS DISTINCT FROM '[]'::jsonb
     OR (v ->> 'exchange_attributes_unchanged')::boolean IS NOT TRUE OR (v ->> 'jobs_owner_definer_path_grants')::boolean IS NOT TRUE
     OR (v ->> 'table_closed_columns_keys')::boolean IS NOT TRUE
     OR v -> 'rel_changed' IS DISTINCT FROM '[]'::jsonb OR v -> 'rel_gone' IS DISTINCT FROM '[]'::jsonb OR v -> 'rel_added' IS DISTINCT FROM w_rel
     OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE OR (v ->> 'anon_ai_app')::int IS DISTINCT FROM 0 OR (v ->> 'ledger')::int IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'APPLY POST-CHECK 20261118180000 FAILED, nothing applied: %', v;
  END IF;
  RAISE NOTICE 'APPLY POST-CHECK 20261118180000 OK: %', v;
END
$postnotice$;

DO $t1$
BEGIN
  PERFORM pg_temp.rec('t_after_apply', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('locks_auth_users_after_apply', (SELECT coalesce(jsonb_agg(DISTINCT l.mode), '[]') FROM pg_locks l WHERE l.pid = pg_backend_pid() AND l.relation = 'auth.users'::regclass));
END $t1$;
-- BACKLOG-4263 PR-10.7 harness: controls, loaded AFTER the migration. Each control is a function returning 'PASS' or
-- 'FAIL: ...'; pg_temp.iso runs one and rolls it back, so controls never see each other's writes.

CREATE FUNCTION pg_temp.iso(fn text) RETURNS text LANGUAGE plpgsql AS $h$
DECLARE x_v text;
BEGIN
  BEGIN
    EXECUTE format('SELECT pg_temp.%I()', fn) INTO x_v;
    RAISE EXCEPTION USING ERRCODE = 'MX001';
  EXCEPTION
    WHEN SQLSTATE 'MX001' THEN NULL;
    WHEN OTHERS THEN x_v := 'FAIL: ERR ' || SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  RETURN x_v;
END $h$;

CREATE FUNCTION pg_temp.nids() RETURNS uuid[] LANGUAGE sql STABLE AS $h$
  SELECT coalesce(array_agg(n.id), '{}') FROM public.ai_app_connect_notices n $h$;
-- the notices not in prev, by fixture user key, ordered by user, provider, replaced
CREATE FUNCTION pg_temp.added(prev uuid[]) RETURNS jsonb LANGUAGE sql STABLE AS $h$
  SELECT coalesce(jsonb_agg(jsonb_build_object('u', pg_temp.ukey(n.user_id), 'p', n.provider, 'r', n.replaced, 's', n.status, 'a', n.attempts,
                                               'at_now', n.connected_at = now(), 'lease', n.lease_until IS NOT NULL, 'sent', n.sent_at IS NOT NULL,
                                               'err', n.last_error)
                            ORDER BY pg_temp.ukey(n.user_id), n.provider, n.replaced), '[]')
    FROM public.ai_app_connect_notices n WHERE NOT (n.id = ANY (prev))
$h$;
CREATE FUNCTION pg_temp.one(u text, p text, r boolean) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_object('u', u, 'p', p, 'r', r, 's', 'due', 'a', 0, 'at_now', true, 'lease', false, 'sent', false, 'err', NULL) $h$;
-- a notice row written directly (claim and done controls); connected_at = now() - age, lease_until = now() + lease
CREATE FUNCTION pg_temp.seed(k text, u uuid, st text, att int, age interval, lease interval DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql AS $h$
DECLARE x_id uuid;
BEGIN
  INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced, connected_at, status, attempts, lease_until, sent_at)
  VALUES (u, 'anthropic', false, now() - age, st, att, now() + lease, CASE WHEN st IN ('sent', 'queued') THEN now() - age END)
  RETURNING ai_app_connect_notices.id INTO x_id;
  PERFORM pg_temp.put(k, x_id::text);
  RETURN x_id;
END $h$;
CREATE FUNCTION pg_temp.nrow(k text) RETURNS jsonb LANGUAGE sql STABLE AS $h$
  SELECT coalesce((SELECT jsonb_build_object('s', n.status, 'a', n.attempts, 'lease', (n.lease_until - now())::text, 'err', n.last_error,
                                             'sent', n.sent_at IS NOT NULL)
                     FROM public.ai_app_connect_notices n WHERE n.id = pg_temp.id(k)), '"gone"'::jsonb) $h$;
-- a claim answer as [{k, a}] ordered by fixture key
CREATE FUNCTION pg_temp.claimed(arr jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $h$
  SELECT coalesce(jsonb_agg(jsonb_build_object('k', coalesce((SELECT f.k FROM pg_temp.pn_fx f WHERE f.v = e ->> 'id'), '?'), 'a', (e ->> 'attempts')::int)
                            ORDER BY coalesce((SELECT f.k FROM pg_temp.pn_fx f WHERE f.v = e ->> 'id'), '?')), '[]')
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(arr) = 'array' THEN arr ELSE '[]'::jsonb END) e
$h$;
CREATE FUNCTION pg_temp.svc(q text) RETURNS text LANGUAGE sql AS $h$ SELECT pg_temp.call_as(NULL, q, 'service_role') $h$;
CREATE FUNCTION pg_temp.claim(n int) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.j(pg_temp.svc(format('SELECT public.ai_app_notice_claim(%s)', coalesce(n::text, 'NULL')))) $h$;
CREATE FUNCTION pg_temp.done_q(k text, att int, st text, err text) RETURNS text LANGUAGE sql STABLE AS $h$
  SELECT format('SELECT to_jsonb(public.ai_app_notice_done(%L::uuid, %s, %L, %L))', pg_temp.id(k), att, st, err) $h$;

-- ---------------------------------------------------------------- one notice per activated connection, right user, provider, replaced
CREATE FUNCTION pg_temp.c_notice() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_b uuid := pg_temp.id('B'); x_p uuid[]; x_c jsonb := '[]'; x_e jsonb := '[]'; x_add jsonb := '[]'; x_act bigint;
BEGIN
  x_p := pg_temp.nids();
  x_c := x_c || pg_temp.consent('n-a1', x_a, 'anthropic'); x_e := x_e || pg_temp.w(pg_temp.q_ex('n-a1', 'anthropic', 101));
  x_add := x_add || jsonb_build_array(pg_temp.added(x_p)); x_p := pg_temp.nids();
  x_c := x_c || pg_temp.consent('n-a2', x_a, 'anthropic'); x_e := x_e || pg_temp.w(pg_temp.q_ex('n-a2', 'anthropic', 102));
  x_add := x_add || jsonb_build_array(pg_temp.added(x_p)); x_p := pg_temp.nids();
  SELECT count(*) INTO x_act FROM public.mcp_connections c WHERE c.user_id = x_a AND c.status = 'active' AND c.provider = 'anthropic';
  x_c := x_c || pg_temp.consent('n-a3', x_a, 'openai'); x_e := x_e || pg_temp.w(pg_temp.q_ex('n-a3', 'openai', 103));
  x_add := x_add || jsonb_build_array(pg_temp.added(x_p)); x_p := pg_temp.nids();
  x_c := x_c || pg_temp.consent('n-b1', x_b, 'anthropic'); x_e := x_e || pg_temp.w(pg_temp.q_ex('n-b1', 'anthropic', 104));
  x_add := x_add || jsonb_build_array(pg_temp.added(x_p));
  RETURN pg_temp.all_of(
    pg_temp.pass((SELECT bool_and(c ->> 'step' = 'approve' AND c ->> 'ok' = 'true') FROM jsonb_array_elements(x_c) c), 'consent ' || x_c::text),
    pg_temp.pass((SELECT bool_and(e = pg_temp.ok_answer()) FROM jsonb_array_elements(x_e) e), 'exchange ' || x_e::text),
    pg_temp.pass(x_add -> 0 = jsonb_build_array(pg_temp.one('A', 'anthropic', false)), 'first ' || (x_add -> 0)::text),
    pg_temp.pass(x_add -> 1 = jsonb_build_array(pg_temp.one('A', 'anthropic', true)), 'reconnect ' || (x_add -> 1)::text),
    pg_temp.pass(x_act = 1, 'earlier connection not replaced, active ' || x_act),
    pg_temp.pass(x_add -> 2 = jsonb_build_array(pg_temp.one('A', 'openai', false)), 'other provider ' || (x_add -> 2)::text),
    pg_temp.pass(x_add -> 3 = jsonb_build_array(pg_temp.one('B', 'anthropic', false)), 'other user ' || (x_add -> 3)::text));
END $c$;

-- ---------------------------------------------------------------- no notice for a refused exchange, a refresh, a second use of a code
CREATE FUNCTION pg_temp.c_none() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_u uuid := pg_temp.id('C'); x_p uuid[]; x_c jsonb := '[]'; x_r jsonb := '{}'; x_mid jsonb; x_rf jsonb;
BEGIN
  x_p := pg_temp.nids();
  x_c := x_c || pg_temp.consent('n-c1', x_u, 'anthropic');
  x_r := x_r || jsonb_build_object('wrong_verifier', pg_temp.w(pg_temp.q_ex('n-c1', 'anthropic', 111, ver_o => pg_temp.ver('n-zz'))));
  x_r := x_r || jsonb_build_object('unknown_code', pg_temp.w(pg_temp.q_ex('n-c0', 'anthropic', 112, code_o => pg_temp.cdl('n-none'))));
  x_c := x_c || pg_temp.consent('n-c2', x_u, 'anthropic');
  UPDATE public.mcp_authorization_codes SET expires_at = now() - interval '1 second' WHERE code_sha256 = sha256(pg_temp.cd('n-c2'));
  x_r := x_r || jsonb_build_object('expired', pg_temp.w(pg_temp.q_ex('n-c2', 'anthropic', 113)));
  x_c := x_c || pg_temp.consent('n-c3', x_u, 'openai');
  x_r := x_r || jsonb_build_object('wrong_secret', pg_temp.w(pg_temp.q_ex('n-c3', 'openai', 114, sec_o => 'pn-wrong-secret')));
  x_r := x_r || jsonb_build_object('same_digests', pg_temp.w(pg_temp.q_ex('n-c3', 'openai', 114, rt_n => 114)));
  x_r := x_r || jsonb_build_object('valid', pg_temp.w(pg_temp.q_ex('n-c3', 'openai', 115)));
  x_mid := pg_temp.added(x_p);
  x_rf := pg_temp.w(format('SELECT public.mcp_refresh(%L, %L::bytea, %L, %L, %L::bytea, %L::bytea)', pg_temp.secret(), pg_temp.dgl(615),
            pg_temp.client(), pg_temp.res(), pg_temp.dgl(117), pg_temp.dgl(617)));
  x_c := x_c || pg_temp.consent('n-c4', x_u, 'anthropic');
  x_r := x_r || jsonb_build_object('token_clash', pg_temp.w(pg_temp.q_ex('n-c4', 'anthropic', 117)));
  x_r := x_r || jsonb_build_object('reused_code', pg_temp.w(pg_temp.q_ex('n-c3', 'openai', 118)));
  RETURN pg_temp.all_of(
    pg_temp.pass((SELECT bool_and(c ->> 'step' = 'approve' AND c ->> 'ok' = 'true') FROM jsonb_array_elements(x_c) c), 'consent ' || x_c::text),
    pg_temp.pass(x_r = jsonb_build_object('wrong_verifier', pg_temp.j('{"ok":false,"error":"invalid_grant"}'), 'unknown_code', pg_temp.j('{"ok":false,"error":"invalid_grant"}'),
                                          'expired', pg_temp.j('{"ok":false,"error":"invalid_grant"}'), 'wrong_secret', pg_temp.j('{"ok":false,"error":"invalid_grant"}'),
                                          'same_digests', pg_temp.j('{"ok":false,"error":"invalid_request"}'), 'valid', pg_temp.ok_answer(),
                                          'token_clash', pg_temp.j('{"ok":false,"error":"invalid_request"}'), 'reused_code', pg_temp.j('{"ok":false,"error":"invalid_grant"}')),
                 'answers ' || x_r::text),
    pg_temp.pass(x_rf ->> 'ok' = 'true', 'refresh ' || x_rf::text),
    pg_temp.pass(x_mid = jsonb_build_array(pg_temp.one('C', 'openai', false)), 'after the valid exchange ' || x_mid::text),
    pg_temp.pass(pg_temp.added(x_p) = jsonb_build_array(pg_temp.one('C', 'openai', false)), 'at the end ' || pg_temp.added(x_p)::text));
END $c$;

-- ---------------------------------------------------------------- the notice insert cannot fail the exchange
CREATE FUNCTION pg_temp.c_insert_fail() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_direct text; x_p uuid[]; x_c jsonb; x_e jsonb; x_fx jsonb;
BEGIN
  EXECUTE 'ALTER TABLE public.ai_app_connect_notices ADD CONSTRAINT x4263_refuse CHECK (false) NOT VALID';
  BEGIN
    INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced) VALUES (x_a, 'anthropic', false);
    x_direct := 'inserted';
  EXCEPTION WHEN OTHERS THEN x_direct := SQLSTATE;
  END;
  x_p := pg_temp.nids();
  x_c := pg_temp.consent('n-f1', x_a, 'anthropic');
  x_e := pg_temp.w(pg_temp.q_ex('n-f1', 'anthropic', 121));
  x_fx := pg_temp.effects(x_a);
  RETURN pg_temp.all_of(
    pg_temp.pass(x_direct = '23514', 'the break did not make an INSERT raise: ' || coalesce(x_direct, 'null')),
    pg_temp.pass(x_c ->> 'ok' = 'true', 'consent ' || x_c::text),
    pg_temp.pass(x_e = pg_temp.ok_answer(), 'exchange ' || coalesce(x_e::text, 'null')),
    pg_temp.pass(x_fx -> 'conns' = '["active anthropic"]' AND (x_fx ->> 'tokens')::int = 2, 'connection ' || x_fx::text),
    pg_temp.pass(pg_temp.added(x_p) = '[]', 'a notice was written ' || pg_temp.added(x_p)::text));
END $c$;

-- ---------------------------------------------------------------- the notice survives the connection row and the client row
CREATE FUNCTION pg_temp.c_survive() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_p uuid[]; x_e jsonb; x_n1 int; x_n2 int; x_n3 int; x_conns bigint;
BEGIN
  x_p := pg_temp.nids();
  PERFORM pg_temp.consent('n-s1', x_a, 'anthropic');
  x_e := pg_temp.w(pg_temp.q_ex('n-s1', 'anthropic', 131));
  x_n1 := jsonb_array_length(pg_temp.added(x_p));
  DELETE FROM public.mcp_connections c WHERE c.user_id = x_a;
  x_n2 := jsonb_array_length(pg_temp.added(x_p));
  DELETE FROM public.mcp_oauth_clients o WHERE o.client_id = pg_temp.client();
  x_n3 := jsonb_array_length(pg_temp.added(x_p));
  SELECT count(*) INTO x_conns FROM public.mcp_connections c WHERE c.user_id = x_a;
  RETURN pg_temp.all_of(
    pg_temp.pass(x_e = pg_temp.ok_answer(), 'exchange ' || coalesce(x_e::text, 'null')),
    pg_temp.pass(x_n1 = 1 AND x_conns = 0, 'setup ' || x_n1 || ' ' || x_conns),
    pg_temp.pass(x_n2 = 1, 'gone with the connection row'),
    pg_temp.pass(x_n3 = 1, 'gone with the client row'));
END $c$;

-- ---------------------------------------------------------------- two exchanges, two users, one transaction: each writes its own row
CREATE FUNCTION pg_temp.c_two_users() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_p uuid[]; x_e1 jsonb; x_e2 jsonb; x_ids bigint;
BEGIN
  x_p := pg_temp.nids();
  PERFORM pg_temp.consent('n-t1', pg_temp.id('A'), 'anthropic');
  PERFORM pg_temp.consent('n-t2', pg_temp.id('B'), 'anthropic');
  x_e1 := pg_temp.w(pg_temp.q_ex('n-t1', 'anthropic', 141));
  x_e2 := pg_temp.w(pg_temp.q_ex('n-t2', 'anthropic', 142));
  SELECT count(DISTINCT n.id) INTO x_ids FROM public.ai_app_connect_notices n WHERE NOT (n.id = ANY (x_p));
  RETURN pg_temp.all_of(
    pg_temp.pass(x_e1 = pg_temp.ok_answer() AND x_e2 = pg_temp.ok_answer(), 'exchange ' || coalesce(x_e1::text, 'null') || coalesce(x_e2::text, 'null')),
    pg_temp.pass(pg_temp.added(x_p) = jsonb_build_array(pg_temp.one('A', 'anthropic', false), pg_temp.one('B', 'anthropic', false)), 'rows ' || pg_temp.added(x_p)::text),
    pg_temp.pass(x_ids = 2, 'distinct ids ' || x_ids),
    pg_temp.pass((SELECT count(*) FROM pg_index i WHERE i.indrelid = 'public.ai_app_connect_notices'::regclass AND i.indisunique) = 1, 'a unique index besides the key'));
END $c$;

-- ---------------------------------------------------------------- no API role but service_role reaches the functions; no role reaches the table
CREATE FUNCTION pg_temp.c_grants() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_role text; x_q text; x_r text; x_bad text := ''; x_n int := 0;
BEGIN
  PERFORM pg_temp.seed('g1', pg_temp.id('A'), 'due', 0, '1 minute');
  FOREACH x_role IN ARRAY ARRAY['anon', 'authenticated', 'mcp_reader'] LOOP
    FOREACH x_q IN ARRAY ARRAY['SELECT public.ai_app_notice_claim(10)', pg_temp.done_q('g1', 0, 'sent', NULL)] LOOP
      x_r := pg_temp.call_as(pg_temp.id('A'), x_q, x_role); x_n := x_n + 1;
      IF x_r NOT LIKE 'ERR 42501 permission denied for function %' THEN x_bad := x_bad || x_role || ' ' || left(x_q, 40) || ' -> ' || left(x_r, 80) || '; '; END IF;
    END LOOP;
  END LOOP;
  FOREACH x_role IN ARRAY ARRAY['anon', 'authenticated', 'mcp_reader', 'service_role'] LOOP
    FOREACH x_q IN ARRAY ARRAY['SELECT count(*) FROM public.ai_app_connect_notices',
                               format('INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced) VALUES (%L, %L, false)', pg_temp.id('A'), 'anthropic'),
                               'UPDATE public.ai_app_connect_notices SET attempts = 0',
                               'DELETE FROM public.ai_app_connect_notices',
                               'TRUNCATE public.ai_app_connect_notices'] LOOP
      x_r := pg_temp.call_as(pg_temp.id('A'), x_q, x_role); x_n := x_n + 1;
      IF x_r NOT LIKE 'ERR 42501 permission denied for table %' THEN x_bad := x_bad || x_role || ' ' || left(x_q, 40) || ' -> ' || left(x_r, 80) || '; '; END IF;
    END LOOP;
  END LOOP;
  RETURN pg_temp.all_of(pg_temp.pass(x_bad = '' AND x_n = 26, x_n || ' calls: ' || x_bad),
                        pg_temp.pass(pg_temp.nrow('g1') = '{"s":"due","a":0,"lease":null,"err":null,"sent":false}', 'row changed ' || pg_temp.nrow('g1')::text));
END $c$;

-- ---------------------------------------------------------------- the inside check: service_role claim works, anything else is refused
CREATE FUNCTION pg_temp.c_caller() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_pc text; x_uc text; x_pd text; x_ud text; x_mid jsonb; x_sc jsonb; x_sd text;
BEGIN
  PERFORM pg_temp.seed('k1', x_a, 'due', 0, '1 minute');
  x_pc := pg_temp.as_user(NULL, 'SELECT public.ai_app_notice_claim(10)');
  x_uc := pg_temp.as_user(x_a, 'SELECT public.ai_app_notice_claim(10)');
  x_pd := pg_temp.as_user(NULL, pg_temp.done_q('k1', 0, 'sent', NULL));
  x_ud := pg_temp.as_user(x_a, pg_temp.done_q('k1', 0, 'sent', NULL));
  x_mid := pg_temp.nrow('k1');
  x_sc := pg_temp.claim(10);
  x_sd := pg_temp.svc(pg_temp.done_q('k1', 1, 'sent', NULL));
  RETURN pg_temp.all_of(
    pg_temp.pass(x_pc LIKE 'ERR P0001 Unauthorized%', 'claim, owner without claims: ' || left(x_pc, 120)),
    pg_temp.pass(x_uc LIKE 'ERR P0001 Unauthorized%', 'claim, owner with a user claim: ' || left(x_uc, 120)),
    pg_temp.pass(x_pd LIKE 'ERR P0001 Unauthorized%', 'done, owner without claims: ' || left(x_pd, 120)),
    pg_temp.pass(x_ud LIKE 'ERR P0001 Unauthorized%', 'done, owner with a user claim: ' || left(x_ud, 120)),
    pg_temp.pass(x_mid = '{"s":"due","a":0,"lease":null,"err":null,"sent":false}', 'row changed by a refused call ' || x_mid::text),
    pg_temp.pass(pg_temp.claimed(x_sc) = '[{"k":"k1","a":1}]', 'service_role claim ' || left(x_sc::text, 200)),
    pg_temp.pass(x_sd = 'true', 'service_role done ' || x_sd),
    pg_temp.pass((pg_temp.nrow('k1') ->> 's') = 'sent', 'after done ' || pg_temp.nrow('k1')::text));
END $c$;

-- ---------------------------------------------------------------- claim: lease, attempts cap, 2-day skip, 30-day prune, keys
CREATE FUNCTION pg_temp.c_claim() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_c1 jsonb; x_c2 jsonb; x_c3 jsonb; x_st jsonb; x_keys boolean; x_first jsonb;
BEGIN
  PERFORM pg_temp.seed('r_fresh', x_a, 'due', 0, '1 minute');
  PERFORM pg_temp.seed('r_old', x_a, 'due', 0, '3 days');
  PERFORM pg_temp.seed('r_tired', x_a, 'due', 5, '1 hour');
  PERFORM pg_temp.seed('r_tired_leased', x_a, 'due', 5, '1 hour', '1 minute');
  PERFORM pg_temp.seed('r_leased', x_a, 'due', 1, '10 minutes', '1 minute');
  PERFORM pg_temp.seed('r_lease_over', x_a, 'due', 1, '10 minutes', '-1 minute');
  PERFORM pg_temp.seed('r_four', x_a, 'due', 4, '1 hour', '-1 second');
  PERFORM pg_temp.seed('r_sent_old', x_a, 'sent', 1, '31 days');
  PERFORM pg_temp.seed('r_due_old', x_a, 'due', 0, '31 days');
  PERFORM pg_temp.seed('r_sent_new', x_a, 'sent', 1, '1 day');
  x_c1 := pg_temp.claim(50);
  SELECT jsonb_object_agg(f.k, pg_temp.nrow(f.k)) INTO x_st FROM pg_temp.pn_fx f WHERE f.k LIKE 'r\_%';
  SELECT bool_and((SELECT array_agg(x ORDER BY x COLLATE "C") FROM jsonb_object_keys(e) x) = ARRAY['attempts', 'connected_at', 'id', 'provider', 'replaced', 'user_id'])
    INTO x_keys FROM jsonb_array_elements(x_c1) e;
  SELECT e INTO x_first FROM jsonb_array_elements(x_c1) e WHERE e ->> 'id' = pg_temp.id('r_fresh')::text;
  x_c2 := pg_temp.claim(50);
  UPDATE public.ai_app_connect_notices n SET lease_until = now() - interval '1 second' WHERE n.id = pg_temp.id('r_fresh');
  x_c3 := pg_temp.claim(50);
  RETURN pg_temp.all_of(
    pg_temp.pass(pg_temp.claimed(x_c1) = '[{"k":"r_four","a":5},{"k":"r_fresh","a":1},{"k":"r_lease_over","a":2}]', 'first claim ' || left(x_c1::text, 300) || ' ' || pg_temp.claimed(x_c1)::text),
    pg_temp.pass(x_keys IS TRUE, 'keys ' || left(x_c1::text, 300)),
    pg_temp.pass(x_first ->> 'user_id' = x_a::text AND x_first ->> 'provider' = 'anthropic' AND x_first -> 'replaced' = 'false' AND x_first ->> 'connected_at' IS NOT NULL,
                 'row ' || coalesce(x_first::text, 'null')),
    pg_temp.pass(x_st = jsonb_build_object(
      'r_fresh', pg_temp.j('{"s":"due","a":1,"lease":"00:05:00","err":null,"sent":false}'),
      'r_old', pg_temp.j('{"s":"skipped","a":0,"lease":null,"err":"stale","sent":false}'),
      'r_tired', pg_temp.j('{"s":"failed","a":5,"lease":null,"err":"attempts","sent":false}'),
      'r_tired_leased', pg_temp.j('{"s":"due","a":5,"lease":"00:01:00","err":null,"sent":false}'),
      'r_leased', pg_temp.j('{"s":"due","a":1,"lease":"00:01:00","err":null,"sent":false}'),
      'r_lease_over', pg_temp.j('{"s":"due","a":2,"lease":"00:05:00","err":null,"sent":false}'),
      'r_four', pg_temp.j('{"s":"due","a":5,"lease":"00:05:00","err":null,"sent":false}'),
      'r_sent_old', pg_temp.j('"gone"'),
      'r_due_old', pg_temp.j('"gone"'),
      'r_sent_new', pg_temp.j('{"s":"sent","a":1,"lease":null,"err":null,"sent":true}')), 'states ' || x_st::text),
    pg_temp.pass(x_c2 = '[]', 'second claim ' || left(x_c2::text, 300)),
    pg_temp.pass(pg_temp.claimed(x_c3) = '[{"k":"r_fresh","a":2}]', 'after the lease ' || left(x_c3::text, 300)));
END $c$;

-- ---------------------------------------------------------------- claim: at most 50, nothing for 0, NULL or a negative limit
CREATE FUNCTION pg_temp.c_cap() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_z jsonb; x_null jsonb; x_neg jsonb; x_big jsonb; x_rest jsonb;
BEGIN
  INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced) SELECT x_a, 'openai', false FROM generate_series(1, 60);
  x_z := pg_temp.claim(0);
  x_null := pg_temp.claim(NULL);
  x_neg := pg_temp.claim(-5);
  x_big := pg_temp.claim(1000);
  x_rest := pg_temp.claim(50);
  RETURN pg_temp.all_of(
    pg_temp.pass(x_z = '[]' AND x_null = '[]' AND x_neg = '[]', 'small limits ' || left(x_z::text, 80) || left(x_null::text, 80) || left(x_neg::text, 80)),
    pg_temp.pass(jsonb_array_length(x_big) = 50, 'limit 1000 gave ' || coalesce(jsonb_array_length(x_big)::text, left(x_big::text, 100))),
    pg_temp.pass(jsonb_array_length(x_rest) = 10, 'the rest gave ' || coalesce(jsonb_array_length(x_rest)::text, left(x_rest::text, 100))));
END $c$;

-- ---------------------------------------------------------------- done: guarded on attempts and on due; vocabulary; error cut to 40
CREATE FUNCTION pg_temp.c_done() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_r jsonb := '{}'; x_st jsonb;
BEGIN
  PERFORM pg_temp.seed('d1', x_a, 'due', 1, '1 minute', '5 minutes');
  PERFORM pg_temp.seed('d2', x_a, 'due', 2, '1 minute', '5 minutes');
  PERFORM pg_temp.seed('d3', x_a, 'due', 1, '1 minute', '5 minutes');
  PERFORM pg_temp.seed('d4', x_a, 'due', 1, '1 minute', '5 minutes');
  PERFORM pg_temp.seed('d5', x_a, 'due', 1, '1 minute', '5 minutes');
  x_r := x_r || jsonb_build_object('stale', pg_temp.svc(pg_temp.done_q('d1', 0, 'sent', NULL)));
  x_r := x_r || jsonb_build_object('stale_row', pg_temp.nrow('d1'));
  x_r := x_r || jsonb_build_object('sent', pg_temp.svc(pg_temp.done_q('d1', 1, 'sent', NULL)));
  x_r := x_r || jsonb_build_object('over_finished', pg_temp.svc(pg_temp.done_q('d1', 1, 'failed', 'late')));
  x_r := x_r || jsonb_build_object('retry', pg_temp.svc(pg_temp.done_q('d2', 2, 'due', repeat('e', 100))));
  x_r := x_r || jsonb_build_object('bad_status', left(pg_temp.svc(pg_temp.done_q('d3', 1, 'bogus', NULL)), 9));
  x_r := x_r || jsonb_build_object('null_status', left(pg_temp.svc(pg_temp.done_q('d3', 1, NULL, NULL)), 9));
  x_r := x_r || jsonb_build_object('queued', pg_temp.svc(pg_temp.done_q('d4', 1, 'queued', NULL)));
  x_r := x_r || jsonb_build_object('no_address', pg_temp.svc(pg_temp.done_q('d5', 1, 'skipped', 'no_address')));
  SELECT jsonb_object_agg(f.k, pg_temp.nrow(f.k)) INTO x_st FROM pg_temp.pn_fx f WHERE f.k LIKE 'd_';
  RETURN pg_temp.all_of(
    pg_temp.pass(x_r = jsonb_build_object('stale', 'false', 'stale_row', pg_temp.j('{"s":"due","a":1,"lease":"00:05:00","err":null,"sent":false}'),
                                          'sent', 'true', 'over_finished', 'false', 'retry', 'true', 'bad_status', 'ERR 22023', 'null_status', 'ERR 22023',
                                          'queued', 'true', 'no_address', 'true'), 'answers ' || x_r::text),
    pg_temp.pass(x_st = jsonb_build_object(
      'd1', pg_temp.j('{"s":"sent","a":1,"lease":null,"err":null,"sent":true}'),
      'd2', jsonb_build_object('s', 'due', 'a', 2, 'lease', NULL, 'err', repeat('e', 40), 'sent', false),
      'd3', pg_temp.j('{"s":"due","a":1,"lease":"00:05:00","err":null,"sent":false}'),
      'd4', pg_temp.j('{"s":"queued","a":1,"lease":null,"err":null,"sent":true}'),
      'd5', pg_temp.j('{"s":"skipped","a":1,"lease":null,"err":"no_address","sent":false}')), 'states ' || x_st::text));
END $c$;

-- ---------------------------------------------------------------- catalogue: the apply post-check, run again
CREATE FUNCTION pg_temp.c_catalog() RETURNS text LANGUAGE plpgsql AS $h$
BEGIN
  EXECUTE $pcq$DO $postnotice$
DECLARE v jsonb; w_changed jsonb; w_added jsonb; w_rel jsonb;
BEGIN
  SELECT jsonb_build_object(
    'exchange_md5', (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure),
    'exchange_md5_before', (SELECT b.src_md5 FROM pg_temp.pn_fn_before b WHERE b.sig = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text),
    'exchange_attributes_unchanged', EXISTS (SELECT 1 FROM pg_temp.pn_fn_before b JOIN pg_proc p ON p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows WHERE b.sig = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text),
    'changed', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pn_fn_before b
         WHERE EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig) AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows AND md5(p.prosrc) = b.src_md5)),
    'gone', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pn_fn_before b WHERE NOT EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig)),
    'added', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pn_fn_before b WHERE b.sig = p.oid::regprocedure::text)),
    'jobs_owner_definer_path_grants', (SELECT count(*) = 2 AND bool_and(p.proowner = 'postgres'::regrole::oid AND p.prosecdef AND p.provolatile = 'v'
          AND p.prolang = (SELECT l.oid FROM pg_language l WHERE l.lanname = 'plpgsql') AND array_to_string(p.proconfig, ',') = 'search_path=""'
          AND (SELECT array_agg(DISTINCT a.grantee::regrole::text ORDER BY a.grantee::regrole::text) FROM aclexplode(p.proacl) a
                WHERE a.privilege_type = 'EXECUTE') = ARRAY['postgres', 'service_role'])
        FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.ai_app_notice_claim(integer)'), to_regprocedure('public.ai_app_notice_done(uuid,integer,text,text)'))),
    'table_closed_columns_keys', (SELECT c.relrowsecurity AND c.relowner = 'postgres'::regrole::oid
          AND NOT EXISTS (SELECT 1 FROM pg_policy y WHERE y.polrelid = c.oid)
          AND NOT EXISTS (SELECT 1 FROM aclexplode(c.relacl) a WHERE a.grantee <> c.relowner)
          AND (SELECT count(*) FROM pg_index i WHERE i.indrelid = c.oid AND i.indisunique) = 1
          AND (SELECT array_agg(k.confrelid::regclass::text) FROM pg_constraint k WHERE k.conrelid = c.oid AND k.contype = 'f') = ARRAY['auth.users']
          AND (SELECT array_agg(a.attname::text ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped)
              = ARRAY['id', 'user_id', 'provider', 'replaced', 'connected_at', 'status', 'attempts', 'lease_until', 'sent_at', 'last_error']
        FROM pg_class c WHERE c.oid = to_regclass('public.ai_app_connect_notices')),
    'rel_changed', (SELECT coalesce(array_agg(b.rel ORDER BY b.rel COLLATE "C"), '{}') FROM pg_temp.pn_rel_before b
         WHERE EXISTS (SELECT 1 FROM pg_class c2 WHERE c2.relnamespace = 'public'::regnamespace AND c2.relname::text = b.rel) AND NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relname::text = b.rel AND c.relkind::text = b.kind AND c.relacl::text IS NOT DISTINCT FROM b.acl
                   AND c.relrowsecurity = b.rls AND c.relforcerowsecurity = b.frls AND c.relowner = b.owner
                   AND (SELECT count(*) FROM pg_policy y WHERE y.polrelid = c.oid) = b.npol)),
    'rel_gone', (SELECT coalesce(array_agg(b.rel ORDER BY b.rel COLLATE "C"), '{}') FROM pg_temp.pn_rel_before b WHERE NOT EXISTS (SELECT 1 FROM pg_class c2 WHERE c2.relnamespace = 'public'::regnamespace AND c2.relname::text = b.rel)),
    'rel_added', (SELECT coalesce(array_agg(c.relname::text ORDER BY c.relname::text COLLATE "C"), '{}') FROM pg_class c
        WHERE c.relnamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pn_rel_before b WHERE b.rel = c.relname::text)),
    'anon_mcp_17', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'anon_ai_app', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^ai_app_'
        AND has_function_privilege('anon', p.oid, 'EXECUTE')),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118180000')) INTO v;
  w_changed := CASE WHEN v ->> 'exchange_md5_before' = '9a33bff2db31288bd77a57489558a65b' THEN '[]'::jsonb ELSE jsonb_build_array('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text) END;
  SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"), '[]') INTO w_added
    FROM unnest(ARRAY['public.ai_app_notice_claim(integer)'::regprocedure::text, 'public.ai_app_notice_done(uuid,integer,text,text)'::regprocedure::text]) x WHERE NOT EXISTS (SELECT 1 FROM pg_temp.pn_fn_before b WHERE b.sig = x);
  SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"), '[]') INTO w_rel
    FROM unnest(ARRAY['ai_app_connect_notices', 'ai_app_connect_notices_due_idx', 'ai_app_connect_notices_pkey', 'ai_app_connect_notices_user_idx']) x WHERE NOT EXISTS (SELECT 1 FROM pg_temp.pn_rel_before b WHERE b.rel = x);
  IF v ->> 'exchange_md5' IS DISTINCT FROM '9a33bff2db31288bd77a57489558a65b'
     OR v -> 'changed' IS DISTINCT FROM w_changed OR v -> 'added' IS DISTINCT FROM w_added OR v -> 'gone' IS DISTINCT FROM '[]'::jsonb
     OR (v ->> 'exchange_attributes_unchanged')::boolean IS NOT TRUE OR (v ->> 'jobs_owner_definer_path_grants')::boolean IS NOT TRUE
     OR (v ->> 'table_closed_columns_keys')::boolean IS NOT TRUE
     OR v -> 'rel_changed' IS DISTINCT FROM '[]'::jsonb OR v -> 'rel_gone' IS DISTINCT FROM '[]'::jsonb OR v -> 'rel_added' IS DISTINCT FROM w_rel
     OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE OR (v ->> 'anon_ai_app')::int IS DISTINCT FROM 0 OR (v ->> 'ledger')::int IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'APPLY POST-CHECK 20261118180000 FAILED, nothing applied: %', v;
  END IF;
  RAISE NOTICE 'APPLY POST-CHECK 20261118180000 OK: %', v;
END
$postnotice$;
$pcq$;
  RETURN 'PASS';
EXCEPTION WHEN OTHERS THEN RETURN 'FAIL: ' || left(SQLERRM, 900);
END $h$;

-- ================================================================ the body before this migration, under a temporary name
-- one case: set up, call function fn as anon, answer and side effects (notices excluded); rolled back
CREATE FUNCTION pg_temp.eq_case(cs text, fn text) RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_u uuid := pg_temp.id('A'); x_k text := 'n-eq-' || cs; x_out text; x_r jsonb; x_prov text := 'anthropic';
BEGIN
  BEGIN
    IF cs = 'openai' THEN x_prov := 'openai'; END IF;
    IF cs IN ('replace', 'token_clash') THEN
      -- token_clash: the earlier connection is of the other provider, so it is not replaced and its tokens stay
      PERFORM pg_temp.consent(x_k || '-pre', x_u, CASE WHEN cs = 'token_clash' THEN 'openai' ELSE x_prov END);
      PERFORM pg_temp.w(pg_temp.q_ex(x_k || '-pre', CASE WHEN cs = 'token_clash' THEN 'openai' ELSE x_prov END, 151, fn));
    END IF;
    IF cs IS DISTINCT FROM 'unknown' THEN PERFORM pg_temp.consent(x_k, x_u, x_prov); END IF;
    IF cs = 'expired' THEN
      UPDATE public.mcp_authorization_codes SET expires_at = now() - interval '1 second' WHERE code_sha256 = sha256(pg_temp.cd(x_k));
    END IF;
    IF cs IN ('replay_ok', 'replay_bad') THEN PERFORM pg_temp.w(pg_temp.q_ex(x_k, x_prov, 152, fn)); END IF;
    x_r := pg_temp.w(CASE cs
      WHEN 'wrong_verifier' THEN pg_temp.q_ex(x_k, x_prov, 153, fn, ver_o => pg_temp.ver('n-zz'))
      WHEN 'replay_bad' THEN pg_temp.q_ex(x_k, x_prov, 153, fn, ver_o => pg_temp.ver('n-zz'))
      WHEN 'unknown' THEN pg_temp.q_ex(x_k, x_prov, 153, fn, code_o => pg_temp.cdl('n-none'))
      WHEN 'wrong_secret' THEN pg_temp.q_ex(x_k, x_prov, 153, fn, sec_o => 'pn-wrong-secret')
      WHEN 'same_digests' THEN pg_temp.q_ex(x_k, x_prov, 153, fn, rt_n => 153)
      WHEN 'token_clash' THEN pg_temp.q_ex(x_k, x_prov, 151, fn)
      WHEN 'wrong_redirect' THEN pg_temp.q_ex(x_k, x_prov, 153, fn, redir_o => 'https://claude.ai/api/mcp/other')
      WHEN 'wrong_resource' THEN pg_temp.q_ex(x_k, x_prov, 153, fn, res_o => 'https://pn-other.example.test/api/mcp')
      ELSE pg_temp.q_ex(x_k, x_prov, 153, fn) END);
    x_out := jsonb_build_object('res', x_r, 'fx', pg_temp.effects(x_u))::text;
    RAISE EXCEPTION USING ERRCODE = 'MX004';
  EXCEPTION WHEN SQLSTATE 'MX004' THEN NULL;
  END;
  RETURN x_out;
END $c$;
CREATE FUNCTION pg_temp.eq_cases() RETURNS text[] LANGUAGE sql IMMUTABLE AS $h$
  SELECT ARRAY['first', 'replace', 'openai', 'wrong_verifier', 'unknown', 'expired', 'replay_ok', 'replay_bad', 'wrong_secret', 'same_digests',
               'token_clash', 'wrong_redirect', 'wrong_resource'] $h$;
CREATE FUNCTION pg_temp.c_equal() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_cs text; x_o text; x_n text; x_bad text := ''; x_seen text[] := '{}'; x_first jsonb;
BEGIN
  FOREACH x_cs IN ARRAY pg_temp.eq_cases() LOOP
    x_o := pg_temp.eq_case(x_cs, 'mcp_exchange_code_x4263old');
    x_n := pg_temp.eq_case(x_cs, 'mcp_exchange_code');
    IF x_o IS DISTINCT FROM x_n THEN
      x_bad := x_bad || x_cs || ': old ' || left(coalesce(x_o, 'null'), 250) || ' new ' || left(coalesce(x_n, 'null'), 250) || '; ';
    END IF;
    x_seen := x_seen || coalesce((x_n::jsonb -> 'res')::text, 'null');
    IF x_cs = 'first' THEN x_first := x_n::jsonb -> 'res'; END IF;
  END LOOP;
  RETURN pg_temp.all_of(
    pg_temp.pass(x_bad = '', x_bad),
    pg_temp.pass(x_first = pg_temp.ok_answer(), 'first ' || coalesce(x_first::text, 'null')),
    pg_temp.pass((SELECT count(DISTINCT s) FROM unnest(x_seen) s) >= 3, 'answers do not differ: ' || array_to_string(x_seen, ' ')));
END $c$;
CREATE FUNCTION pg_temp.eq_report() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_cs text; x_out jsonb := '{}';
BEGIN
  FOREACH x_cs IN ARRAY pg_temp.eq_cases() LOOP
    x_out := x_out || jsonb_build_object(x_cs, pg_temp.eq_case(x_cs, 'mcp_exchange_code')::jsonb);
  END LOOP;
  RETURN x_out::text;
END $c$;
CREATE FUNCTION pg_temp.with_old(fn text) RETURNS text LANGUAGE plpgsql AS $h$
DECLARE x_v text; x_ok boolean := false;
BEGIN
  BEGIN
    EXECUTE $ocq$CREATE FUNCTION public.mcp_exchange_code_x4263old(p_secret text, p_code_digest bytea, p_code_verifier text, p_client_id text, p_redirect_uri text,
                                                    p_resource text, p_at_digest bytea, p_rt_digest bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_code   public.mcp_authorization_codes%ROWTYPE;
  v_used   public.mcp_authorization_codes%ROWTYPE;
  v_user   uuid;
  v_redir  text;
  v_pepper smallint;
  v_n      integer;
  v_scope  text;
BEGIN
  /*BODY:4263-5*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;
  IF (octet_length(p_code_digest) = 32 AND octet_length(p_at_digest) = 32 AND octet_length(p_rt_digest) = 32
      AND p_at_digest IS DISTINCT FROM p_rt_digest) IS NOT TRUE THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END IF;

  -- token insert failure: everything in this block is rolled back (code not used up)
  BEGIN
  UPDATE public.mcp_authorization_codes k
     SET used_at = now()
   WHERE k.code_sha256 = sha256(p_code_digest)
     AND k.used_at IS NULL
     AND k.expires_at > now()
  RETURNING k.* INTO v_code;

  IF v_code.code_sha256 IS NULL THEN
    -- a used code presented again: the connection is removed only when the request is otherwise
    -- valid for that code (client, verifier, and redirect address when sent)
    SELECT k.* INTO v_used
      FROM public.mcp_authorization_codes k
     WHERE k.code_sha256 = sha256(p_code_digest)
       AND k.used_at IS NOT NULL;
    IF v_used.code_sha256 IS NOT NULL THEN
      SELECT c.user_id INTO v_user FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
      IF (v_used.client_id = p_client_id
          AND (p_redirect_uri IS NULL OR v_used.redirect_uri = p_redirect_uri)
          AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
          AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_used.code_challenge) IS TRUE THEN
        DELETE FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay', 'ok', now());
      ELSIF public._mcp_bump('replay_refused:' || v_used.connection_id::text, interval '1 hour', 5) IS NOT DISTINCT FROM 'ok' THEN
        -- at most 5 refused-replay events per connection per hour; the response is the same either way
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay_refused', 'ok', now());
      END IF;
    END IF;
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  -- a rejected redemption uses up the code and removes its pending connection
  IF (v_code.client_id = p_client_id
      AND (p_redirect_uri IS NULL OR v_code.redirect_uri = p_redirect_uri)
      AND v_code.resource = p_resource
      AND EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = v_code.redirect_uri)
      AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
      AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_code.code_challenge) IS NOT TRUE THEN
    DELETE FROM public.mcp_connections c
     WHERE c.id = v_code.connection_id AND c.status = 'pending'
    RETURNING c.user_id INTO v_user;
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
    VALUES (v_user, v_code.connection_id, 'code_rejected', 'ok', now());
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  UPDATE public.mcp_connections c
     SET status = 'active', activated_at = now()
   WHERE c.id = v_code.connection_id
     AND c.status = 'pending'
  RETURNING c.user_id, c.redirect_uri, c.scope INTO v_user, v_redir, v_scope;
  IF v_user IS NULL THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;

  DELETE FROM public.mcp_connections c
   WHERE c.user_id = v_user AND c.redirect_uri = v_redir AND c.id <> v_code.connection_id AND c.status = 'active';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at, rows_returned)
    VALUES (v_user, v_code.connection_id, 'reconnect_replaced', 'ok', now(), v_n);
  END IF;

  SELECT s.pepper_version INTO v_pepper FROM public.mcp_settings s WHERE s.id;
  BEGIN
    INSERT INTO public.mcp_tokens (token_sha256, connection_id, kind, pepper_version, expires_at) VALUES
      (sha256(p_at_digest), v_code.connection_id, 'access', v_pepper, now() + interval '1 hour'),
      (sha256(p_rt_digest), v_code.connection_id, 'refresh', v_pepper, now() + interval '30 days');
  EXCEPTION WHEN unique_violation OR not_null_violation THEN
    RAISE EXCEPTION USING ERRCODE = 'MC001', MESSAGE = 'mcp token insert failed';
  END;
  RETURN jsonb_build_object('ok', true, 'token_type', 'Bearer', 'expires_in', 3600, 'scope', v_scope);   /*SCOPE:exchange*/
  EXCEPTION WHEN SQLSTATE 'MC001' THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END;
END
$fn$;$ocq$;
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.mcp_exchange_code_x4263old(text, bytea, text, text, text, text, bytea, bytea) TO anon';
    SELECT md5(p.prosrc) = 'ab6a9345c55ab69c77347d9b37e92e9d' AND p.prosecdef INTO x_ok
      FROM pg_proc p WHERE p.oid = to_regprocedure('public.mcp_exchange_code_x4263old(text,bytea,text,text,text,text,bytea,bytea)');
    EXECUTE format('SELECT pg_temp.%I()', fn) INTO x_v;
    RAISE EXCEPTION USING ERRCODE = 'MX003';
  EXCEPTION WHEN SQLSTATE 'MX003' THEN NULL;
    WHEN OTHERS THEN x_v := 'FAIL: ERR ' || SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  IF x_ok IS NOT TRUE THEN
    RETURN 'FAIL: the old copy is not installed at md5 ab6a9345c55ab69c77347d9b37e92e9d (' || coalesce(x_v, '') || ')';
  END IF;
  RETURN x_v;
END $h$;

-- ================================================================ re-run of the migration
DO $rerun$
BEGIN
  EXECUTE $migq$-- ============================================================================
-- Migration: a notice when an AI app connects (BACKLOG-4263 PR-10.7)
--
-- New table public.ai_app_connect_notices: one row per AI-app connection that turned active, read later by the
--   portal's email job (a later PR). It holds whose account, which provider, whether the connection replaced an
--   earlier one, and the sending state. No token, no connection id, no text supplied by the app. RLS on, no policy,
--   no privilege for any API role; reached only through the two functions below.
-- Replaced (pre-check below): mcp_exchange_code (anon, portal secret checked first, as before). The one change: after
--   the tokens are stored, one INSERT into the new table, in its own BEGIN ... EXCEPTION WHEN OTHERS block (one
--   subtransaction per exchange), so an error there never fails the exchange. The answer is unchanged. 'replaced'
--   is v_n > 0, the row count of the DELETE of the user's earlier active connection to the same redirect address.
--   The body is otherwise character-identical to the body of 20261118130000 (the marker comment aside).
-- New: ai_app_notice_claim(p_limit) and ai_app_notice_done(p_id, p_attempts, p_status, p_error), SECURITY DEFINER,
--   EXECUTE service_role only, each refusing inside unless the request's role is service_role.
--   claim: housekeeping first (a due notice older than 2 days -> skipped 'stale'; a due notice tried 5 times with its
--   lease ended -> failed; finished notices older than 30 days deleted), then up to min(p_limit, 50) due notices with
--   no live lease, FOR UPDATE SKIP LOCKED, each leased for 5 minutes and its attempts incremented. Answers a JSON
--   array of {id, user_id, provider, replaced, connected_at, attempts}.
--   done: sets the status ('due' releases the lease for a retry) only while the row is due and its attempts equal
--   p_attempts; the error code is cut to 40 characters. Answers true when a row changed.
-- Existing rows: none changed. Connections made before this file get no notice.
-- Pre-check: mcp_exchange_code is at the body of 20261118130000 (md5 ab6a9345c55ab69c77347d9b37e92e9d) or already at this
--   file's body (md5 9a33bff2db31288bd77a57489558a65b); otherwise nothing is applied.
-- Re-runnable: CREATE TABLE / INDEX IF NOT EXISTS, CREATE OR REPLACE.
-- Rollback: supabase/tests/backlog-4263-notice/rollback-20261118180000.sql (run it before any rollback of
--   20261118130000).
-- ============================================================================

DO $pre4263notice$
DECLARE v_md5 text;
BEGIN
  SELECT md5(p.prosrc) INTO v_md5 FROM pg_catalog.pg_proc p
   WHERE p.oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)');
  IF v_md5 IS NULL OR v_md5 NOT IN ('ab6a9345c55ab69c77347d9b37e92e9d', '9a33bff2db31288bd77a57489558a65b') THEN
    RAISE EXCEPTION 'BACKLOG-4263: public.mcp_exchange_code is not at the expected body (md5 %)', coalesce(v_md5, 'missing');
  END IF;
END
$pre4263notice$;

-- ============================================================================ table
CREATE TABLE IF NOT EXISTS public.ai_app_connect_notices (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL REFERENCES auth.users (id) ON DELETE CASCADE,
  provider     text NOT NULL CHECK (provider IN ('anthropic', 'openai')),
  replaced     boolean NOT NULL,
  connected_at timestamptz NOT NULL DEFAULT now(),
  status       text NOT NULL DEFAULT 'due' CHECK (status IN ('due', 'sent', 'queued', 'failed', 'skipped')),
  attempts     smallint NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  lease_until  timestamptz NULL,
  sent_at      timestamptz NULL,
  last_error   text NULL CHECK (last_error IS NULL OR char_length(last_error) <= 40)
);
CREATE INDEX IF NOT EXISTS ai_app_connect_notices_due_idx ON public.ai_app_connect_notices (connected_at) WHERE status = 'due';
CREATE INDEX IF NOT EXISTS ai_app_connect_notices_user_idx ON public.ai_app_connect_notices (user_id);
ALTER TABLE public.ai_app_connect_notices ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.ai_app_connect_notices FROM PUBLIC, anon, authenticated, service_role;
REVOKE TRUNCATE ON TABLE public.ai_app_connect_notices FROM anon, authenticated;

-- ============================================================================ exchange (anon)
-- 4263 PR-5: answers the connection's scope. 4263 PR-10.7: records one notice when the connection turns active.
-- Intentionally callable by anon: OAuth token exchange for a registered client (portal secret checked inside)
CREATE OR REPLACE FUNCTION public.mcp_exchange_code(p_secret text, p_code_digest bytea, p_code_verifier text, p_client_id text, p_redirect_uri text,
                                                    p_resource text, p_at_digest bytea, p_rt_digest bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_code   public.mcp_authorization_codes%ROWTYPE;
  v_used   public.mcp_authorization_codes%ROWTYPE;
  v_user   uuid;
  v_redir  text;
  v_pepper smallint;
  v_n      integer;
  v_scope  text;
BEGIN
  /*BODY:4263-10.7*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;
  IF (octet_length(p_code_digest) = 32 AND octet_length(p_at_digest) = 32 AND octet_length(p_rt_digest) = 32
      AND p_at_digest IS DISTINCT FROM p_rt_digest) IS NOT TRUE THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END IF;

  -- token insert failure: everything in this block is rolled back (code not used up)
  BEGIN
  UPDATE public.mcp_authorization_codes k
     SET used_at = now()
   WHERE k.code_sha256 = sha256(p_code_digest)
     AND k.used_at IS NULL
     AND k.expires_at > now()
  RETURNING k.* INTO v_code;

  IF v_code.code_sha256 IS NULL THEN
    -- a used code presented again: the connection is removed only when the request is otherwise
    -- valid for that code (client, verifier, and redirect address when sent)
    SELECT k.* INTO v_used
      FROM public.mcp_authorization_codes k
     WHERE k.code_sha256 = sha256(p_code_digest)
       AND k.used_at IS NOT NULL;
    IF v_used.code_sha256 IS NOT NULL THEN
      SELECT c.user_id INTO v_user FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
      IF (v_used.client_id = p_client_id
          AND (p_redirect_uri IS NULL OR v_used.redirect_uri = p_redirect_uri)
          AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
          AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_used.code_challenge) IS TRUE THEN
        DELETE FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay', 'ok', now());
      ELSIF public._mcp_bump('replay_refused:' || v_used.connection_id::text, interval '1 hour', 5) IS NOT DISTINCT FROM 'ok' THEN
        -- at most 5 refused-replay events per connection per hour; the response is the same either way
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay_refused', 'ok', now());
      END IF;
    END IF;
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  -- a rejected redemption uses up the code and removes its pending connection
  IF (v_code.client_id = p_client_id
      AND (p_redirect_uri IS NULL OR v_code.redirect_uri = p_redirect_uri)
      AND v_code.resource = p_resource
      AND EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = v_code.redirect_uri)
      AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
      AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_code.code_challenge) IS NOT TRUE THEN
    DELETE FROM public.mcp_connections c
     WHERE c.id = v_code.connection_id AND c.status = 'pending'
    RETURNING c.user_id INTO v_user;
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
    VALUES (v_user, v_code.connection_id, 'code_rejected', 'ok', now());
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  UPDATE public.mcp_connections c
     SET status = 'active', activated_at = now()
   WHERE c.id = v_code.connection_id
     AND c.status = 'pending'
  RETURNING c.user_id, c.redirect_uri, c.scope INTO v_user, v_redir, v_scope;
  IF v_user IS NULL THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;

  DELETE FROM public.mcp_connections c
   WHERE c.user_id = v_user AND c.redirect_uri = v_redir AND c.id <> v_code.connection_id AND c.status = 'active';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at, rows_returned)
    VALUES (v_user, v_code.connection_id, 'reconnect_replaced', 'ok', now(), v_n);
  END IF;

  SELECT s.pepper_version INTO v_pepper FROM public.mcp_settings s WHERE s.id;
  BEGIN
    INSERT INTO public.mcp_tokens (token_sha256, connection_id, kind, pepper_version, expires_at) VALUES
      (sha256(p_at_digest), v_code.connection_id, 'access', v_pepper, now() + interval '1 hour'),
      (sha256(p_rt_digest), v_code.connection_id, 'refresh', v_pepper, now() + interval '30 days');
  EXCEPTION WHEN unique_violation OR not_null_violation THEN
    RAISE EXCEPTION USING ERRCODE = 'MC001', MESSAGE = 'mcp token insert failed';
  END;
  -- 4263 PR-10.7: one notice for the connection that just turned active, read later by the email job. In its own
  -- block: any error here discards the notice only; the exchange and its answer are unchanged.
  BEGIN
    INSERT INTO public.ai_app_connect_notices (user_id, provider, replaced)
    SELECT c.user_id, c.provider, v_n > 0 FROM public.mcp_connections c WHERE c.id = v_code.connection_id;   /*NOTICE:exchange*/
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN jsonb_build_object('ok', true, 'token_type', 'Bearer', 'expires_in', 3600, 'scope', v_scope);   /*SCOPE:exchange*/
  EXCEPTION WHEN SQLSTATE 'MC001' THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END;
END
$fn$;
REVOKE ALL ON FUNCTION public.mcp_exchange_code(text, bytea, text, text, text, text, bytea, bytea) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mcp_exchange_code(text, bytea, text, text, text, text, bytea, bytea) TO anon;

-- ============================================================================ email job (service_role)
CREATE OR REPLACE FUNCTION public.ai_app_notice_claim(p_limit integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_rows jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN   /*CALLER:claim*/
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  UPDATE public.ai_app_connect_notices n
     SET status = 'skipped', last_error = 'stale', lease_until = NULL
   WHERE n.id IN (SELECT x.id FROM public.ai_app_connect_notices x
                   WHERE x.status = 'due' AND x.connected_at < now() - interval '2 days'   /*STALE:skip*/
                   LIMIT 500 FOR UPDATE SKIP LOCKED);
  UPDATE public.ai_app_connect_notices n
     SET status = 'failed', last_error = coalesce(n.last_error, 'attempts'), lease_until = NULL
   WHERE n.id IN (SELECT x.id FROM public.ai_app_connect_notices x
                   WHERE x.status = 'due' AND x.attempts >= 5 AND (x.lease_until IS NULL OR x.lease_until <= now())
                   LIMIT 500 FOR UPDATE SKIP LOCKED);
  DELETE FROM public.ai_app_connect_notices n
   WHERE n.id IN (SELECT x.id FROM public.ai_app_connect_notices x
                   WHERE x.status IN ('sent', 'queued', 'failed', 'skipped') AND x.connected_at < now() - interval '30 days'   /*KEEP:30d*/
                   LIMIT 500 FOR UPDATE SKIP LOCKED);
  WITH c AS (
    SELECT x.id FROM public.ai_app_connect_notices x
     WHERE x.status = 'due'
       AND x.attempts < 5   /*CAP:attempts*/
       AND (x.lease_until IS NULL OR x.lease_until <= now())   /*LEASE:free*/
       AND x.connected_at >= now() - interval '2 days'   /*STALE:claim*/
     ORDER BY x.connected_at, x.id
     LIMIT least(greatest(coalesce(p_limit, 0), 0), 50)   /*CAP:limit*/
     FOR UPDATE SKIP LOCKED),
  u AS (
    UPDATE public.ai_app_connect_notices n
       SET attempts = n.attempts + 1, lease_until = now() + interval '5 minutes'
      FROM c
     WHERE n.id = c.id
    RETURNING n.id, n.user_id, n.provider, n.replaced, n.connected_at, n.attempts)
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'user_id', u.user_id, 'provider', u.provider, 'replaced', u.replaced,
                                               'connected_at', u.connected_at, 'attempts', u.attempts) ORDER BY u.connected_at, u.id), '[]'::jsonb)   /*KEYS:claim*/
    INTO v_rows
    FROM u;
  RETURN v_rows;
END
$fn$;
REVOKE ALL ON FUNCTION public.ai_app_notice_claim(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ai_app_notice_claim(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.ai_app_notice_done(p_id uuid, p_attempts integer, p_status text, p_error text)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_n integer;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN   /*CALLER:done*/
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF (p_status IN ('due', 'sent', 'queued', 'failed', 'skipped')) IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ai_app_notice_done: unknown status';
  END IF;
  UPDATE public.ai_app_connect_notices n
     SET status = p_status,
         last_error = left(p_error, 40),   /*CUT:error*/
         lease_until = NULL,
         sent_at = CASE WHEN p_status IN ('sent', 'queued') THEN now() ELSE n.sent_at END
   WHERE n.id = p_id
     AND n.attempts = p_attempts   /*GUARD:attempts*/
     AND n.status = 'due';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n = 1;
END
$fn$;
REVOKE ALL ON FUNCTION public.ai_app_notice_done(uuid, integer, text, text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ai_app_notice_done(uuid, integer, text, text) TO service_role;

-- Post-check: bodies, attributes and grants of the three functions; the table closed; the anon-callable mcp count.
DO $post4263notice$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'exchange', (SELECT md5(p.prosrc) = '9a33bff2db31288bd77a57489558a65b' AND p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""'
                        AND has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
                        AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
                   FROM pg_catalog.pg_proc p WHERE p.oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure),
    'jobs', (SELECT bool_and(p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""' AND p.proowner = 'postgres'::regrole::oid
                             AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND NOT has_function_privilege('anon', p.oid, 'EXECUTE')
                             AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')) AND count(*) = 2
               FROM pg_catalog.pg_proc p WHERE p.oid IN ('public.ai_app_notice_claim(integer)'::regprocedure,
                                                         'public.ai_app_notice_done(uuid,integer,text,text)'::regprocedure)),
    'table', (SELECT c.relrowsecurity AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_policy y WHERE y.polrelid = c.oid)
                     AND NOT has_table_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
                     AND NOT has_table_privilege('authenticated', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
                     AND NOT has_table_privilege('service_role', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
                FROM pg_catalog.pg_class c WHERE c.oid = 'public.ai_app_connect_notices'::regclass),
    'anon_mcp', (SELECT count(*) FROM pg_catalog.pg_proc p
                  WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE')),
    'anon_jobs', (SELECT count(*) FROM pg_catalog.pg_proc p
                   WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^ai_app_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))) INTO v;
  IF (v ->> 'exchange')::boolean IS NOT TRUE OR (v ->> 'jobs')::boolean IS NOT TRUE OR (v ->> 'table')::boolean IS NOT TRUE
     OR (v ->> 'anon_mcp')::int IS DISTINCT FROM 17 OR (v ->> 'anon_jobs')::int IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'BACKLOG-4263: notice post-check failed: %', v;
  END IF;
END
$post4263notice$;
$migq$;
  PERFORM pg_temp.rec('rerun', to_jsonb('ok'::text));
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_temp.rec('rerun', to_jsonb('ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 400)));
END
$rerun$;
-- ================================================================ controls
DO $ctl$
DECLARE c text;
BEGIN
  FOREACH c IN ARRAY ARRAY['c_notice', 'c_none', 'c_insert_fail', 'c_survive', 'c_two_users', 'c_grants', 'c_caller', 'c_claim', 'c_cap', 'c_done', 'c_catalog'] LOOP
    PERFORM pg_temp.rec('CTL_' || c, to_jsonb(pg_temp.iso(c)));
  END LOOP;
  PERFORM pg_temp.rec('t_after_controls', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('CTL_c_equal', to_jsonb(pg_temp.with_old('c_equal')));
  PERFORM pg_temp.rec('REPORT_exchange_answers', pg_temp.j(pg_temp.iso('eq_report')));
  PERFORM pg_temp.rec('old_copy_gone', to_jsonb(to_regprocedure('public.mcp_exchange_code_x4263old(text,bytea,text,text,text,text,bytea,bytea)') IS NULL));
  PERFORM pg_temp.rec('notices_after_controls', to_jsonb((SELECT count(*) FROM public.ai_app_connect_notices)));
  PERFORM pg_temp.rec('t_after_equal', to_jsonb(clock_timestamp()));
END
$ctl$;
-- ================================================================ mutations
DO $m_M01_no_insert$
DECLARE v text; ok boolean;
BEGIN
  BEGIN
    
    EXECUTE $mutq$CREATE OR REPLACE FUNCTION public.mcp_exchange_code(p_secret text, p_code_digest bytea, p_code_verifier text, p_client_id text, p_redirect_uri text,
                                                    p_resource text, p_at_digest bytea, p_rt_digest bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_code   public.mcp_authorization_codes%ROWTYPE;
  v_used   public.mcp_authorization_codes%ROWTYPE;
  v_user   uuid;
  v_redir  text;
  v_pepper smallint;
  v_n      integer;
  v_scope  text;
BEGIN
  /*BODY:4263-10.7*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;
  IF (octet_length(p_code_digest) = 32 AND octet_length(p_at_digest) = 32 AND octet_length(p_rt_digest) = 32
      AND p_at_digest IS DISTINCT FROM p_rt_digest) IS NOT TRUE THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END IF;

  -- token insert failure: everything in this block is rolled back (code not used up)
  BEGIN
  UPDATE public.mcp_authorization_codes k
     SET used_at = now()
   WHERE k.code_sha256 = sha256(p_code_digest)
     AND k.used_at IS NULL
     AND k.expires_at > now()
  RETURNING k.* INTO v_code;

  IF v_code.code_sha256 IS NULL THEN
    -- a used code presented again: the connection is removed only when the request is otherwise
    -- valid for that code (client, verifier, and redirect address when sent)
    SELECT k.* INTO v_used
      FROM public.mcp_authorization_codes k
     WHERE k.code_sha256 = sha256(p_code_digest)
       AND k.used_at IS NOT NULL;
    IF v_used.code_sha256 IS NOT NULL THEN
      SELECT c.user_id INTO v_user FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
      IF (v_used.client_id = p_client_id
          AND (p_redirect_uri IS NULL OR v_used.redirect_uri = p_redirect_uri)
          AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
          AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_used.code_challenge) IS TRUE THEN
        DELETE FROM public.mcp_connections c WHERE c.id = v_used.connection_id;
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay', 'ok', now());
      ELSIF public._mcp_bump('replay_refused:' || v_used.connection_id::text, interval '1 hour', 5) IS NOT DISTINCT FROM 'ok' THEN
        -- at most 5 refused-replay events per connection per hour; the response is the same either way
        INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
        VALUES (v_user, v_used.connection_id, 'code_replay_refused', 'ok', now());
      END IF;
    END IF;
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  -- a rejected redemption uses up the code and removes its pending connection
  IF (v_code.client_id = p_client_id
      AND (p_redirect_uri IS NULL OR v_code.redirect_uri = p_redirect_uri)
      AND v_code.resource = p_resource
      AND EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = v_code.redirect_uri)
      AND p_code_verifier ~ '^[A-Za-z0-9._~-]{43,128}$'
      AND public._mcp_b64url(sha256(convert_to(p_code_verifier, 'UTF8'))) = v_code.code_challenge) IS NOT TRUE THEN
    DELETE FROM public.mcp_connections c
     WHERE c.id = v_code.connection_id AND c.status = 'pending'
    RETURNING c.user_id INTO v_user;
    INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at)
    VALUES (v_user, v_code.connection_id, 'code_rejected', 'ok', now());
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  UPDATE public.mcp_connections c
     SET status = 'active', activated_at = now()
   WHERE c.id = v_code.connection_id
     AND c.status = 'pending'
  RETURNING c.user_id, c.redirect_uri, c.scope INTO v_user, v_redir, v_scope;
  IF v_user IS NULL THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;

  DELETE FROM public.mcp_connections c
   WHERE c.user_id = v_user AND c.redirect_uri = v_redir AND c.id <> v_code.connection_id AND c.status = 'active';
