    ok := (SELECT md5(p.prosrc) = '36aa3b0c28cd5ae07b5b1adb9d14087a' FROM pg_proc p WHERE p.oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)')) AND EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = 'public.ai_app_connect_notices'::regclass AND a.attname = 'connection_id' AND NOT a.attisdropped);
    v := pg_temp.iso('c_survive');
    RAISE EXCEPTION USING ERRCODE = 'MX002';
  EXCEPTION WHEN SQLSTATE 'MX002' THEN NULL;
    WHEN OTHERS THEN v := 'MUTANT ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 300); ok := false;
  END;
  PERFORM pg_temp.rec('MUT_M08_fk_to_connection_cascade', jsonb_build_object('applied', ok, 'control', 'c_survive', 'red', left(v, 4) IS DISTINCT FROM 'PASS', 'result', left(v, 400)));
END
