-- post-check holds. Order: run this BEFORE any rollback of 20261118130000 (whose pre-check requires the exchange at
-- md5 ab6a9345c55ab69c77347d9b37e92e9d). It does not depend on the rollbacks of 20261118140000, 20261118150000 or 20261118160000.
DO $prenoticer$
DECLARE v_md5 text;
