  SELECT md5(p.prosrc) INTO v_md5 FROM pg_proc p WHERE p.oid = to_regprocedure('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)');
  IF v_md5 IS DISTINCT FROM '9a33bff2db31288bd77a57489558a65b' THEN
    RAISE EXCEPTION 'ROLLBACK 20261118180000: mcp_exchange_code is not at the body 20261118180000 wrote (md5 %)', coalesce(v_md5, 'missing');
  END IF;
