    RAISE EXCEPTION 'ROLLBACK 20261118180000: an object 20261118180000 created is missing';
  END IF;
  RAISE NOTICE 'ROLLBACK 20261118180000: dropping % notice rows', (SELECT count(*) FROM public.ai_app_connect_notices);
