DROP FUNCTION public.ai_app_notice_done(uuid, integer, text, text);
DROP TABLE public.ai_app_connect_notices;
DELETE FROM supabase_migrations.schema_migrations WHERE version = '20261118180000';

DO $postnoticer$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'exchange_md5', (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure),
    'exchange_attributes_unchanged', EXISTS (SELECT 1 FROM pg_temp.pn_rb_fn b JOIN pg_proc p ON p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows WHERE b.sig = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text),
    'changed', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pn_rb_fn b
         WHERE EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig) AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows AND md5(p.prosrc) = b.src_md5)),
    'gone', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pn_rb_fn b WHERE NOT EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig)),
    'added', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pn_rb_fn b WHERE b.sig = p.oid::regprocedure::text)),
    'table_gone', to_regclass('public.ai_app_connect_notices') IS NULL,
    'rel_changed', (SELECT coalesce(array_agg(b.rel ORDER BY b.rel COLLATE "C"), '{}') FROM pg_temp.pn_rb_rel b
         WHERE EXISTS (SELECT 1 FROM pg_class c2 WHERE c2.relnamespace = 'public'::regnamespace AND c2.relname::text = b.rel) AND NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relname::text = b.rel AND c.relkind::text = b.kind AND c.relacl::text IS NOT DISTINCT FROM b.acl
                   AND c.relrowsecurity = b.rls AND c.relforcerowsecurity = b.frls AND c.relowner = b.owner
                   AND (SELECT count(*) FROM pg_policy y WHERE y.polrelid = c.oid) = b.npol)),
    'rel_gone', (SELECT coalesce(array_agg(b.rel ORDER BY b.rel COLLATE "C"), '{}') FROM pg_temp.pn_rb_rel b WHERE NOT EXISTS (SELECT 1 FROM pg_class c2 WHERE c2.relnamespace = 'public'::regnamespace AND c2.relname::text = b.rel)),
    'rel_added', (SELECT coalesce(array_agg(c.relname::text ORDER BY c.relname::text COLLATE "C"), '{}') FROM pg_class c
        WHERE c.relnamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pn_rb_rel b WHERE b.rel = c.relname::text)),
    'anon_mcp_17', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118180000')) INTO v;
  IF v ->> 'exchange_md5' IS DISTINCT FROM 'ab6a9345c55ab69c77347d9b37e92e9d'
     OR v -> 'changed' IS DISTINCT FROM jsonb_build_array('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text) OR v -> 'added' IS DISTINCT FROM '[]'::jsonb
     OR v -> 'gone' IS DISTINCT FROM '["ai_app_notice_claim(integer)", "ai_app_notice_done(uuid,integer,text,text)"]'::jsonb
     OR (v ->> 'exchange_attributes_unchanged')::boolean IS NOT TRUE OR (v ->> 'table_gone')::boolean IS NOT TRUE
     OR v -> 'rel_changed' IS DISTINCT FROM '[]'::jsonb OR v -> 'rel_gone' IS DISTINCT FROM '["ai_app_connect_notices", "ai_app_connect_notices_due_idx", "ai_app_connect_notices_pkey", "ai_app_connect_notices_user_idx"]'::jsonb
     OR v -> 'rel_added' IS DISTINCT FROM '[]'::jsonb
     OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE OR (v ->> 'ledger')::int IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261118180000 FAILED, nothing changed: %', v;
  END IF;
  RAISE NOTICE 'ROLLBACK POST-CHECK 20261118180000 OK: %', v;
END
$postnoticer$;
$rbq$;
  PERFORM pg_temp.rec('rollback', to_jsonb('ok'::text));
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_temp.rec('rollback', to_jsonb('ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 900)));
END
$rb$;
DO $after$
DECLARE x_e jsonb;
BEGIN
  PERFORM pg_temp.rec('rb_exchange_md5', to_jsonb((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure)));
  PERFORM pg_temp.rec('rb_md5_equals_before_apply', to_jsonb((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure)
                                                             = (SELECT v #>> '{}' FROM pg_temp.pn_out WHERE k = 'exchange_md5_before_apply')));
  PERFORM pg_temp.rec('rb_objects_gone', to_jsonb(to_regclass('public.ai_app_connect_notices') IS NULL AND to_regprocedure('public.ai_app_notice_claim(integer)') IS NULL AND to_regprocedure('public.ai_app_notice_done(uuid,integer,text,text)') IS NULL));
  PERFORM pg_temp.rec('rb_ledger', to_jsonb((SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118180000')));
  PERFORM pg_temp.rec('locks_auth_users_after_rollback', (SELECT coalesce(jsonb_agg(DISTINCT l.mode), '[]') FROM pg_locks l WHERE l.pid = pg_backend_pid() AND l.relation = 'auth.users'::regclass));
  PERFORM pg_temp.consent('n-rb1', pg_temp.id('A'), 'anthropic');
  x_e := pg_temp.w(pg_temp.q_ex('n-rb1', 'anthropic', 191));
  PERFORM pg_temp.rec('rb_exchange_still_works', to_jsonb(x_e = pg_temp.ok_answer()));
  PERFORM pg_temp.rec('t_end', to_jsonb(clock_timestamp()));
  RAISE EXCEPTION 'NOTICE_RESULT %', (SELECT jsonb_object_agg(k, v) FROM pg_temp.pn_out);
END
$after$;
